window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200120-6","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"区民委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「しながわ地域貢献活動展」の開催","agenda":"「しながわ地域貢献活動展」の開催","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ここの参加団体、６０団体とありますけれども、どのような形で募集をしたのか、どういう形でこの中で選ばれたのか教えてください。","respondent":"遠藤協働・国際担当課長","answer":"こちらにつきましては、９月の段階で広報しながわで２月にこのようなイベントを出しますので、参加団体、こちらで募集いたしますということで応募いただいた団体となっております。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"「第３０回伝統の技と味／しながわ展」の開催","agenda":"「第３０回伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"こんの副委員長","kind":"意見","question":"参考までにまず１点ですけれども、先ほど松澤委員からも話があったのとちょっと関連するのですが、ここに出店されている味のほうのお店は毎年同じところが設定されているなという感じなのですけれども、これはやはり決まっていることなのか、それとも毎年違うところも出店をされるように工夫はされているのか、その辺が１点と。","respondent":"山崎商業・ものづくり課長","answer":"それから小学校のほうはもともと伝統工芸の方々が、これは教育委員会と連携をしながら、伝統工芸に親しむという意味で、ふれあい教室を大体学校数全体の３分の１ぐらいの小学校に当たるような形で選定をしまして。","voiceIndex":24,"id":"exchange-002"},{"speaker":"こんの副委員長","kind":"確認","question":"出店は公募をされているということでよくわかりました。その中でも同じところというところはいろいろな皆さん思いがあってのことだと思うので、よくわかりました。周知については学校全体、小学校、中学校、いわゆる学校のお手紙配布物の中の１つとしてそういうのが入っているかどうかというところを最後、確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"イベントの周知に関しましては、おっしゃいましたとおり、全ての学校にご周知を申し上げているところです。","voiceIndex":26,"id":"exchange-003"}]},{"id":"topic-03","title":"「ウーマンズビジネスグランプリ２０２０」の開催","agenda":"「ウーマンズビジネスグランプリ２０２０」の開催","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"一番上の３行のところの２行目から優れたアイデアを持つ女性の区内での創業を促進し、区内産業の活性化を図ると書いてあるのですけれども、これは具体的には一体どういうことなのでしょうか。「区内での創業を促進」ということは具体的にどういうことかということです。","respondent":"山崎商業・ものづくり課長","answer":"区民の方の比率としますと、３５％ぐらいがファイナリストにいるのですけれども、特に区内創業を誘導させていただいてはいますが、ビジネスモデルによってはなかなかグローバルなところもありますので、区内で必ずしも創業に結びついているというわけでもないです。","voiceIndex":38,"id":"exchange-004"}]},{"id":"topic-04","title":"「ＳＨＩＮＡＧＡＷＡイノベーションフォーラム２０２０ｉｎ五反田バレー」の開催","agenda":"「ＳＨＩＮＡＧＡＷＡイノベーションフォーラム２０２０ｉｎ五反田バレー」の開催","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"のめり込むというほどのお金の出し方ではもしかしたらないのかもしれないけれども、重点を置くべきようなことかという問題意識が、こういう報告を受けると、どうしても出てきてしまうのです。そこら辺を課長としてはどうお考えでしょう。重点の置き方をどうお考えかとちょっと思いました。","respondent":"山崎商業・ものづくり課長","answer":"今年、本委員会でも中小ベンチャー企業支援について取り上げていただいて、７月に五反田バレーの現状などもご紹介をさせていただいた中の１つのユニットとして計画をされたＰＲのイベント事業という位置づけです。","voiceIndex":45,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"私の頭には昨年の消費税増税のことなんかがあって、そこで廃業せざるを得なかったという商店のお声も最近伺ったりしましたので、それの支援をどうしたらいいのかということもちょっと考えたりもしますので、それと比べてということも念頭にあったりしたもので、比べるような問題ではないかもしれませんけれども、どこに区の予算を使っていけばいいかということがありましたので、ちょっとお伺いしてみました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-006"},{"speaker":"木村委員","kind":"意見","question":"本当に、委員から大変重要なお金の使い方ということでしょうけれども、それは別に置いておいて、この４Ｇと５Ｇとの違いを我々は全然わからないのですよ。４Ｇがどうであって、そして５Ｇになればどのようになるのかというのを何か簡単に説明してください。","respondent":"山崎商業・ものづくり課長","answer":"そうすると、例えばすごくわかりやすいかどうかあれなのですけれども、防犯のための防犯カメラが設置されていて、カメラに画像が映るというのはデータが通信されて映るのですけれども、今までは例えば木村委員のお顔が認知できないような画質だったものが。","voiceIndex":48,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"おくの委員の意見と全く今回は真逆で質問をさせていただきたいと思っています。この時期によくこの講演をやっていただけましたという私は思いで質問しようと思うのですけれども、まず５ＧのＧは何の英語の略でしょうか。","respondent":"山崎商業・ものづくり課長","answer":"世代をあらわすジェネレーションのＧです。","voiceIndex":50,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"その中のいわゆる情報量のスピードとかそういう意味において、５Ｇになった時代にどうなっていくかを、やはり技術的なことや事務的な作業等を含めて、やはりそれにかかわる行政の方も１人でも多く、せっかく７００万、８００万、税金をかけてやるわけですから、もう立ち見が出るぐらい、この講演を聞いていただきたいと私は思っているのですが、その辺についてはいかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"ちなみに現在、もう既に２２２名の応募があるということで、おそらく昨年もそうであったのですけれども、キャパの４００名は集まっていただけるものと考えています。","voiceIndex":52,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうすると、なぜ今からこの５Ｇの、まず講演をやるわけですからというと、私の個人的意見でいうと、この行政のいわゆるサービス。だって２４時間、３６５日、きちんとプログラミングすれば、ＡＩだったら仕事ができてしまうのですから。ですからせっかくこういう講演を７００万、８００万かけてやるのでしたら、もうぜひ１人でも多くの方にこれを聞いてもらって、こういう時代が来るのだよと。","respondent":"山崎商業・ものづくり課長","answer":"時代のテーマに合わせたこうしたイベントの開催を通じまして、そうした将来の課題の共有でありますとか、いろいろ語る議論の場は、先ほどと重複しますけれども品川の大きな一つの産業の特徴であります情報通信業の集積などの活性化とあわせまして。","voiceIndex":54,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"これは漠然としていて、逆に言うと５Ｇを使うとどういった形で少子化問題がぐっと解決できるのか、経済格差がなくなるというのがぐっとわかるようになれば、先ほども委員が言っていた品川区民もそういうのがわかりやすくていいのかと思ったのですけれども、そういうのはまだ全然わかり得る話ではないのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"今、おっしゃったような少子化に対応するとか、あるいはいろいろな意味の格差を是正するとかということはその５Ｇそのものがやるのではなくて、そこにデータがたまったものをこういう角度でこんなタイミングで抽出すれば。","voiceIndex":56,"id":"exchange-011"},{"speaker":"湯澤委員","kind":"意見","question":"それとあと、どういうふうにアピールしているかというのは。","respondent":"山崎商業・ものづくり課長","answer":"そうしたことが３月の下旬に品川区内中小向けに来年度の説明会を行うときも来ていただいて、いろいろなお話とともにちょっと付加価値を高めていくようなおつき合いをさせていただいているという状況です。","voiceIndex":63,"id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"積極的に取りあげていってもらいたいと自分も思っているのですけれども、ぜひそれだけに来場者も多く。前のときに、１１月がどのぐらい来ていたのか気にもなっていたのですけれども、もし数字が出れば、１１月のときのものを教えてもらえると。これからも進めていってもらいたいということで、これは要望にします。もしわからないようならいいです。ちょっとさっき見ながら、どのぐらいかと思ったので。","respondent":"山崎商業・ものづくり課長","answer":"それから２回目が区民委員会でも以前ご報告をさせていただきました目黒のアマゾンでやったものです。こちらも企業７０社で１１７名の参加ということで、盛況なうちに過去２回とも終了させていただいている状況です。","voiceIndex":65,"id":"exchange-013"}]},{"id":"topic-05","title":"公益財団法人十四世六平太記念財団との連携に関する協定","agenda":"公益財団法人十四世六平太記念財団との連携に関する協定","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"ただ、この品川区民が能楽にふれ親しむ機会を拡大することで、品川区民が心豊かで生き生きと暮らせるまちづくりを推進するというのは具体的にはどういったイメージというか、もう少し詳しく、どうすると心豊かで生き生きと暮らせるまちづくりを推進という形になっていくのかというのをお答えいただけますか。","respondent":"古巻文化観光課長","answer":"能楽がすぐに具体的に心豊かなというところに結びつくかというと、なかなか難しいところがありますけれども、やはりさまざまなこういった伝統芸能にふれ親しむことによって、さらに今までにあまり能楽というものが。","voiceIndex":72,"id":"exchange-014"},{"speaker":"湯澤委員","kind":"意見","question":"もう１つ、これまでの取り組みの実績として区内の小中学校でも体験講座の実施とかあったと書いてあるのですけれども、私も実は小学校のときに能を体験したことがあって、そのときはもう本当にただただ恥ずかしくてしようがないみたいな感じだったのですが、小中学生は体験してどういった反応というか感想を持たれていたのかがわかれば、お聞かせいただければと思います。","respondent":"古巻文化観光課長","answer":"ちょっと感想という意味では答弁になっていないのですけれども、そのように考えているところです。","voiceIndex":74,"id":"exchange-015"},{"speaker":"湯澤委員","kind":"質問","question":"所管が違うのに失礼しました。最後に能楽堂なのですけれども、喜多能楽堂以外に区内には能楽堂はどのぐらいあるのでしょうか。","respondent":"古巻文化観光課長","answer":"区内は能楽堂はございません。ここだけです。都内でも珍しい施設です。","voiceIndex":76,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論でお伺いしたいのですけれども、私もこの品川区に生まれ育ちましたが、私個人の感覚で言うならば、能という伝統芸能というか文化とかいうのが、ずっと子どものときから、そんなに思ってなかったというのか、感覚的に全くないのです。そのときもたしか質問をしたけれども、なぜ急に能とかになってしまったのかという質問をしたような記憶があるのです。","respondent":"古巻文化観光課長","answer":"これは今の地に移転してきたのが、たしか昭和３０年ぐらいだと聞いているのですけれども、それよりも以前に今、委員からお話があったとおり、お祭りであるとか古い伝統文化が息づいているものがいろいろとあるうちの品川の土着のといいましょうか。","voiceIndex":78,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"能楽堂があってという。いろいろある伝統文化のアイテムの一つとして、品川区として協定をして応援していきたいと考えていますと、中途半端にしないでずっとそういうアピールは続けていっていただいて、せっかく今できたわけですから、あえてこういう質問をさせていただきましたけれども、反対しているのではなくて、それはいいではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-018"},{"speaker":"こんの副委員長","kind":"質問","question":"天候によっては残念ながらというところもあったりして、天候のこともさることながら、協定によって、これまでよりも、よりこういう能楽を皆さんに見ていただく機会が増えていくと理解していいのでしょうか。応募をされた方が結構いらっしゃって、見てみたい。品川区でこういうのが見れるのだというので、結構人気と私は理解しているのですが、その点はどうなのでしょうか。","respondent":"古巻文化観光課長","answer":"ですから、傾向というか全体としては能楽のいろいろな公演とかにふれられる機会は当然増えてくると考えますし、増やしていかなければいけないと考えているところです。","voiceIndex":81,"id":"exchange-019"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ぜひ、お願いしたいと思います。私もまだ一度も見たことはないのですが、あとは天候です。お外でされるので、屋外なので、そこをどうするか。せっかくなので屋内だとまた趣が違ってしまいますし、屋外というところ、会場の用意も大変かと思いますけれども、その点、これから詳しいことをされていくと思いますが、その点も考慮していただきながら、機会を増やしていただければと要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"そういうのも協定を結んだ際に、違うと言われればそれまでなのですけれども、能だけではなくそういう雅楽も一緒に融合させられるような、地域と関連づけてやれるような機会があるととてもうれしいと思うのですが、そういった観点はどうでしょうか。","respondent":"古巻文化観光課長","answer":"雅楽といった意味でいうと、今回のこの能楽堂の話とはまたちょっと別の話になりますけれども、品川区の文化プログラムの助成制度を去年から、東京２０２０大会に向けた文化プログラムの助成制度をつくっておりますが。","voiceIndex":84,"id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"今、伝統芸能という話があったのですが、文化芸術・スポーツのまちづくり条例に基づいてこの辺も出てきていると思うのですけれども、今後、いろいろな面での施策展開を、さっきちょっとお話があったと思いますが、老朽化と維持管理とありましたけれども、その辺はどう捉えていくのか、もしある程度の方向が出ているのだったら教えてください。","respondent":"古巻文化観光課長","answer":"まだ今後の能楽堂のあり方等については現時点で具体的にどうこうとお話しできるだけのものはないのですけれども、せっかくあるもので、それなりにやはり年数がたっているものですので。","voiceIndex":86,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、うまく連携をとっていただきたいということを要望にして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-023"}]},{"id":"topic-06","title":"大森貝塚解説アプリ","agenda":"大森貝塚解説アプリ","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、１回、特別、予特か決特でお伺いしたのですけれども、大井町から大森駅に向かう電車に乗っておりました。小学校、大井第一のときによく遊びに来たなと思い出しながら乗っていて、大森駅に着くちょっと手前に、小さ目でもう１つ大森貝塚があるではないかと。大森貝塚かと思った石碑が立っていたのですけれども、あれは大田区に入っていたと思うのですが、あれは何なのでしょうか。","respondent":"古巻文化観光課長","answer":"大森貝墟碑というのが大田区にありまして、そちら大田区側に建てられたもので、あくまでも貝塚自体は遺跡庭園のところが遺跡の国の指定地になっています。あちらになりますけれども、関連する近隣のといったことで、大田区に建てたものと認識しております。","voiceIndex":96,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"そのときにたしか安藤部長が課長時代にその質問をさせていただいて、今日はそのことをお伺いするのではなくて、あのとき聞いたのは私はどちらが本家か元祖かみたいに伺って、きちんとした答弁をいただいたのですけれども、もちろん品川区側の大森貝塚だと答弁をいただいたのですが、今日の質問はそれではなくて、貝墟ですよね。貝墟。大森貝塚の質問をするのは、私だけではないですよね。","respondent":"古巻文化観光課長","answer":"学術的なところの正確さはいろいろ文化財係のほうからも答弁させていただいているところですけれども、品川区内に大森貝塚があるというのは、紛れもない事実だと認識しておりますので、しっかりその担当する管理職として、整理をしておく必要があると思います。","voiceIndex":98,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はこういう立場でいろいろ伺えるからわかるのですけれども、一般の方が見たときにわからないのです。大森貝塚と大田区に入っているわけですから、どういう趣旨でそうやっているのか、きちんと担当といいますか、課なのかもしれませんけれども、そこはしっかりと押さえておいていただきたいと思いますので、そこだけ約束というか、答弁いただけませんか。","respondent":"古巻文化観光課長","answer":"この歴史館に行くときに大森駅から行くこともありますので、前は何度か通っていると認識しておりますが、大きな看板という意味でいうとちょっと目に入っていなかったのかもしれません。","voiceIndex":100,"id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"全然関係ない話になってしまうかもしれないのですけれども、貝塚つながりで居木橋貝塚というものがありまして、芳水小学校まで行く中を下りる坂を昨日歩いていたら貝塚がやはりあったのです。それが途中で放置された状態で、あれは何も発掘もせずにそのまま建て替えられてしまうのかと。全然違う質問なのですけれども、素朴な疑問でありまして。","respondent":"古巻文化観光課長","answer":"歴史館の中で紹介している部分もありますけれども、発掘云々になりますと文化財係の所管になりますので、そのあたりはそちらでどのような形になっているのか把握を今しておりませんので、そのような形ですみません。","voiceIndex":102,"id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですけれども、このアプリなのですが、スマートフォンのアプリということで、スマートフォンを持っていない方は、例えば観覧料が無料になる７０歳以上の方とか、障害のある方、区内の小・中学生とかそういう方はなかなかもしかしたらスマートフォンをお持ちでない方がいるのかなと思うのですけれども、スマートフォンを持っている方でないと、その機能というか。","respondent":"古巻文化観光課長","answer":"あくまでも、スマホ対応ということでご検討いただければと思います。","voiceIndex":106,"id":"exchange-028"},{"speaker":"湯澤委員","kind":"質問","question":"本当に若い世代とか外国人向けにつくっていただくというそういう世代とかそういう方たちに非常にいい取り組みだと思います。ただ、大森貝塚の見学者は近年減っていったりしているから、よりこういうものをしようと思ったりしているのでしょうか。それとも別にそういうのは関係なく、今回さらに新しい技術を取り入れたりして、より多くの方に知っていただこうという試みなのでしょうか。","respondent":"古巻文化観光課長","answer":"どちらかというと、大森貝塚と品川歴史館を結びつけるというか、付近に品川歴史館がありますし、また逆に言うと歴史館の近隣に大森貝塚があるという状況がありますので、大森貝塚をご覧になって、また歴史館に来ていただいて品川区の歴史について触れていただくとか。","voiceIndex":108,"id":"exchange-029"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１件確認なのですけれども、これは主催がしながわ観光協会だから、今回そこの課でやられるわけですよね。商店街が絡んでいるので、こちらの商業・ものづくり課だと思っていたのですけれども、確認です。","respondent":"古巻文化観光課長","answer":"しながわ観光協会の企画ですので、所管としては文化観光課です。商業振興もありますけれども、商店街も観光資源の一つとして位置づけておりますので、こういった形で商店街を観光資源として使わせていただいているです。","voiceIndex":121,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"期間が短く、すぐ工事をしていただいて再開できるということも感謝しておりますが、私の記憶だと何年か前にもし違ったら指摘していただきたいのですけれども、プール本体の天井が災害等、地震等ではなくて落ちたときとかあると思うのですけれども、やはりプールというか湿気というか、そういうところはやはり湿気等の関係で天井は壊れやすいというか落ちやすくなっているのでしょうか。","respondent":"中元スポーツ推進課長","answer":"私のほうで情報収集させていただいたところ、やはりおっしゃるとおり、平成２６年ですか、プール側の天井が一部やはり落下をしたことがあったということで、技術職のほうの職員にも庶務課長を通じて確認をしていただいているのですが。","voiceIndex":126,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、課長から適切な管理ということで安心はしておりますが、すばらしい施設で区民の方が利用させていただいているので、やはり今回は負傷者がいらっしゃらなかったから幸いしましたけれども、天井の落下によって負傷者が出たら大変ですから、管理とあと検査ができればしていただいて、気持ちよく施設が使えるように、日ごろから目を配っていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33808,"voices":130}},{"id":"r02-20200120-7","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"厚生委員会","time":"午後 １時００分～午後 ４時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年陳情第６４号 障害児者総合支援施設の施設長を設置するよう区長に求める陳情","agenda":"令和元年陳情第６４号 障害児者総合支援施設の施設長を設置するよう区長に求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の総合支援施設は、指定管理者が３法人入り、そのほかに日精看も入っているという施設になったわけですけれども、そういう点では、施設の維持管理が品川区の障害者福祉課が行っているという状況になっていると思います。その委託会社や委託内容についても教えていただきたいと思います。そこら辺の消防計画との関係の仕組みについても教えていただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"ご質問の職員体制についてです。区職員の人数といたしましては、常勤的な勤務で配置されている職員が１人と、非常勤の形で２人配置しております。それから委託している内容ですけれども、設備の管理をする会社が入っておりまして、そこで１人から２人、職員が配置されております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今のお話ですと、委託の会社というのは、設備と受付と清掃と、それぞれに３つの事業所が入っているということで考えていいのでしょうか。今のご説明だと、消防計画に基づいて訓練がされているということで、消防法のところからも消防計画は立てなければならないということになっているので、消防計画は立てられていると思うのですけれども、なぜ、この陳情者の質問がこのようなことになったのか。","respondent":"築山障害者施策推進担当課長","answer":"消防計画に基づき、災害の際に適切な対応ができるようにしていくため、日ごろの訓練を定期的に実施していくという考えです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、施設長がいなくても、区が統括の管理をしているわけですから、区が責任を持って指揮できるという体制になっているということで考えていいでしょうか。それと全体の消防計画というのは、区がつくったということでいいのかという点だけ確認をお願いしたいと思います。防災マニュアルの点からどうなっているのかということについてもお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"例えば、災害対策のことも計画に位置づけております。災害、また、復旧までの計画や大雨、強風等の対策や備蓄品のこと等も計画に盛り込んでいるという状況です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう既に防災マニュアルも含めた消防計画ということでつくられていて、備蓄物資などもそれにきちんと明示されているということで考えていいでしょうか。ちなみに、備蓄物資だと、何日分くらい想定されているのかについてもお聞かせいただきたいと思います。利用者や利用者の家族などへの防災マニュアルを含めた消防計画の公開という点について、実際はどうなっているのかについてもお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"それから消防計画の公開についてですが、施設を利用するに当たりましては、重要事項説明書等で、事前に必要なことについては説明をさせていただいているところです。その中で、必要な情報等についてはご説明をさせていただいて、施設の利用につなげているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、安心しておいでいただいて大丈夫ですよという説明をされているということなのでしょうか。その消防計画というのも、公開するという形でされているのか。公開のことを少しお聞かせいただきたいと思います。そういう点で言うと、備蓄が３日分では少ないのではないかなという思いがするのですけれども、その点についてもお願いします。","respondent":"築山障害者施策推進担当課長","answer":"それから福祉避難所につきましては、現在、防災課と協議中で準備を進めているところです。それから備蓄品につきましては、３日分というのが一般的なところかと認識しております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"防災マニュアルを含めた消防計画についての公開なのですけれども、これは公開できない理由が何かあるのでしょうか。公開されたものを見て、こういうところはどうなのかという不安などを新たに出していただくことが、さらに安全につながっていき、そのようなところも充実させることができるのではないかなと思うのです。その点についてはいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"計画等の公開につきましては、防犯上の理由で、例えば、不特定多数の方へ公開することによって、防犯上の点から注意が必要かと思っているところです。ただ、先ほども言いましたとおり、必要なことについては、説明等をしてご安心いただけるように整えていきたいと思っています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"多分、陳情された方も、そのようにさまざま質問されて、なおかつ、こういう陳情を出されたのかなと思うのです。そういう点では、防犯上、公開できないというのも、例えばホームページに載っていますよなど、公開の仕方もいろいろあると思うのです。防犯上、そういう方に公開するのは、さまざまな事件もあったりしたので難しい部分があるのかもしれないですが、そこら辺の考え方だけ、最後にお願いします。","respondent":"築山障害者施策推進担当課長","answer":"利用する方につきましては、重要事項説明書等での説明を行っておりますので、その際に必要なことについてはご説明したいと考えています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"少し重なるところもあるかもしれませんが、障害児者総合支援施設全体の管理は区がされているということなのですけれども、今、常駐の職員は何人いらっしゃるのでしょうか。どういう立場でいらっしゃるのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"常駐では、係長級の職員が１名おります。立場としましては、複数の委託事業者が入っておりますので、建物の管理上の調整等を図るという役割で配置されております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"私も、年末に改めて利用者の方々と施設を見せていただいたのですけれども、改善すべき点が、ハード面でもいろいろあるように感じました。そうしたこともきちんとチェックして、求められるレベルに持っていくというのも、全体を見る方がいらっしゃるとスムーズにいくのかなと感じるのです。その点は、今後、どのような感じでやっていかれるのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"区と指定管理者の協力体制のもと、一体的な施設運営ができるように取り組んでいるところですので、総合支援施設として何らかの発信をしていく際も、区と指定管理者との協力体制のもと、情報発信等々をしていければと考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"事業者にとっても、さらには施設外の人にとっても、今のところとてもわかりにくいのです。課長が言われたように、「センター長」と呼ぶのか、「施設長」と呼ぶのか、それはいろいろ位置づけがあると思いますけれども、少なくとも、区としてわかりやすい、あるいは施設としての発信者であり、ちゃんと連携をしていく立場の人がわかるように存在させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"本日結論を出して、不採択でお願いいたします。今の説明とやりとりで、問題ないことの確認がとれました。１つ言うのであれば、当然、複合体で入っているわけだから、いろいろな問い合わせがある。これは、施設長の問題なのであれだけれども、運営自体に問題がない。災害が起こったときにも問題ないということなので、今回、この内容自体は不採択にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"西村委員","kind":"意見","question":"私も、本日結論を出すで、不採択でお願いいたします。今、渡部委員がおっしゃったのと同じなのですけれども、先ほど、課長がおっしゃったとおり、統括防火管理者は区が担うというところで、私は説明のとおり理解いたしましたので、今回、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。今の体制の中で、安全・安心が一定確認されたということが、１つ大きくあります。今後、今の指定管理のあり方が３年間というところで、また新たに施設全体の施設管理のあり方が出てくると思います。とりあえず、３年後をしっかり目指して、安全な体制を敷いていただきたいなということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この陳情は、災害時のことが心配で出された陳情だと思いますけれども、今の区の説明でも、施設の管理は区が係長を配置して、統括防火責任者も区の係長が担っているということで、３法人、それから日精看とも連携をとりながら進めているということで、まだ改善すべき点はさまざまあるとは思うのですが、そういう体制の中でとれるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということと、それから陳情に対しては不採択と考えております。現状に問題がないとは思っておりません。施設長も、私は、いたほうがベターだと考えています。少なくとも、形というよりは、機能の面で足りないことがないようにしていただきたいという思いを込めて、ただ、施設長という名前にはこだわらないという意味では不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-015"}]},{"id":"topic-02","title":"令和元年陳情第６５号 特定相談・障害児相談支援事業所を増やすよう区長に求める陳情","agenda":"令和元年陳情第６５号 特定相談・障害児相談支援事業所を増やすよう区長に求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この陳情に「昨年度の実計画相談件数を明らかにしていません」と書かれているのですけれども、平成３０年度の実計画相談件数がわかったら教えていただけないでしょうか。","respondent":"松山障害者福祉課長","answer":"ちなみに、平成３０年度の直近の実績は、年間利用者数ということで捉えておりますのは、２,９２７件ということで、平成３０年度の実績については報告します。","voiceIndex":39,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは、７月２日の厚生委員会のときにご報告いただいた障害福祉計画実績というところでの１２ページの数字ですね。これが年間の計画の延べ実績ということになると、１２か月で割ると２４３件というすごく少ない件数になってしまうのです。そこのところをご説明いただけたらと思います。そこら辺が何となくごちゃごちゃしていてわかりにくいという状況になっているので、少しご説明いただけないでしょうか。","respondent":"松山障害者福祉課長","answer":"今後、次年度につきましては、新たな計画を立てる、特に、今、ニーズ調査も行っておりますので、そちらを踏まえて計画相談件数を見込む。国の標準担当件数を目安にして、必要数を見込んでいきたいと考えています。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、２,９２７件で見込み数が１,８５２件だったわけですから、１,１００件もないくらいがモニタリングと考えていいということ。それを、今度はモニタリングを３か月だったり、必要な人にとっては毎月だったり、もっと頻度を加えてやるとなると、延べ２,９２７件というのがもっとどんと上がるという見込みが出てくるのではないかという考え方なのでしょうか。","respondent":"松山障害者福祉課長","answer":"本来であれば、計画相談に乗らない相談やアウトリーチ型の委託相談事業所が行わなければならないものでございまして、機能的に計画相談支援事業所と委託相談という機能が一緒になってしまっているので、事業所にとっては業務がかなり加重でありますし、利用者側から。","voiceIndex":43,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、２,１００人いるわけです。例えば、これだともう終わりぐらいと考えていますよとか、６割ぐらいまではいったのではないかとか、そういうおおよその目安というのですか。まだまだ、こんなに増やしていくという考えなのですよというあたりは、どう考えられているのかについても、少しお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"今後の展開についてです。今年度、６事業所増やしましたけれども、来年度につきましても、同数以上は増やしたいと考えています。ただ、何割というのは、やはりニーズ調査を行っておりますので、そのニーズ調査も踏まえて、分析しながら見込んでいきたいと考えております。","voiceIndex":45,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に計画相談事業所が極端に少なくて、実際にいろいろと話を伺ったところでは、１人１００件くらい計画を組んでいるというお話を伺ってきました。さらに、来年度も今年度以上に、それでも足りない。本当に大変なところからの出発で、ご苦労もあると思うのですけれども、一番大変なのは障害者、当事者の皆様ですので、今後とも増設と充実に向けて取り組んでいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。説明の中でも、今後、また継続して増やしていくです。陳情の理由の下から５行目あたりでしょうか。これは、区民の方々から何か相談事があるときはしっかり相談に乗っていただくということは、区は最低限やっているわけだから、その辺の齟齬なども生じていますけれども、これからもその辺はしっかり進めていただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほど、課長からご説明がありましたように、今後も支援事業所を検討していると説明がありましたし、想定される相談件数を分析していただきながら、引き続きお願いしたいと思いますので、本日は不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この計画相談というところが、やはり障害者福祉のサービスを受けるに当たっての一番の根本的なところになると思いますので、もともと遅れた状態からの出発なので、障害者福祉課の皆様、本当にご苦労されているとは思うのですけれども、これからもそれを取り返すというところで、ぜひ増やして充実させていくということで、取り組みを進めていただきたいという要望も込めて、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"あべ委員","kind":"意見","question":"ですので、たとえ６事業所増えたとはいえ、こうした陳情が出てくるというのは理解できるところではあるのですけれども、区側でも、年間これだけ増やしていくというのはいろいろ大変なこともあったかと思いますし、また、今後も同程度ということをご答弁いただきましたので、まずはそうした形で数を増やしていただいて、同時に質のチェックということも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-024"}]},{"id":"topic-03","title":"令和元年陳情第６７号 地域自立支援協議会の議事録における反対意見の掲載見送りに関する陳情","agenda":"令和元年陳情第６７号 地域自立支援協議会の議事録における反対意見の掲載見送りに関する陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、障害者福祉がどうなっていくのかということは多くの方々の強い関心事だと思うのです。だからこそ、正確な情報公開が求められていると思うのです。そういう点で言えば、要旨にするのはどうなのかということは、私は疑問があるところです。この議事録要旨は誰が作成しているのかをお聞かせいただきたい。そもそも、なぜ要旨にしているのか。そのことについて伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"その旨は、発言された委員にも確認し、趣旨が変わらないということもきちんと確認した上で掲載しているです。なお、陳情者の方へも、既に同様の説明をしています。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、その人の趣旨は変えない、最終的には、発言者に確認ということになるわけなのですけれども、傍聴者の方々も実際に傍聴をしているわけですから、そのときに感じた感覚と要旨にまとめられたことが、「えっ」と思う中身というのはどうなのかなと思うのです。私は、この間の平成２９年、平成３０年、令和元年ということで、それぞれの議事録を見比べてみたのですけれども、すごく変わっています。","respondent":"松山障害者福祉課長","answer":"地域自立支援協議会は、皆様の関心が高くて、それは非常にありがたいことなのですけれども、各委員個人へのお問い合わせもございまして、各委員から率直に発言するのがなかなか難しいというお声もいただきましたので、事務局と会長とで相談しまして、円滑な運営を図るために。","voiceIndex":63,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、そのようなことが諮られたという記憶はなかったのですけれども、地域自立支援協議会の中で、議事録のつくり方は名前を出さない、要旨の箇条書きのような形にしていきますよということが会長から皆様に、「どうですか」と言うよりは、「そのようにします」というご報告があったということなのですか。それとも、区からこのようにしたいのだけれどもどうかということで会長に言われたのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのように選ばれて、責任ある立場としてその会議に参加していて、それが公開という形になっているわけですから、議事録を要旨にしないと思い切った発言ができないというのは、私は、逆に区から公開という姿勢にしていただきたいなと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、傍聴者にとってこのような意見があったということは、議事録に残すべき文言なのではないかという趣旨の陳情ですけれども、そういう点からしても、今、情報公開という時代ですから、これだけ傍聴者がいて、公開されていることを公にするというのは当然だし、私は全文議事録にしていただきたいということで要望もしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"今の質疑を伺いながら、公的な記録を残すということと、発言者を守るということと、両方を行っていくのはなかなか難しいことだなと感じました。区として、地域自立支援協議会の議事録とありますけれども、抄録というか、要録のようなものだと思います。どのような手順で、どなたがつくっているのか。どなたがというのは、どのような機関でつくっていらっしゃるのですか。","respondent":"松山障害者福祉課長","answer":"ただし、こちらの陳情に載せられているような趣旨につきましては、そこを削っているということではなく、ご意見としてコンパクトにまとめた形で掲載しておりますので、会長のおっしゃられる趣旨は、要旨の中に載っているという認識です。","voiceIndex":69,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"少し細かいことですけれども、これは、例えばレコーダーに録音して、それを職員の方が課内でテープを起こして、それを読みながら要約をつくっているという手順なのでしょうか。","respondent":"松山障害者福祉課長","answer":"これについては、おっしゃられたとおりです。","voiceIndex":71,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"ごめんなさい。陳情から少し離れます。いつも気になっていて、これだけ忙しい障害者福祉課の中で、外注できるところは外注したほうがいいのではないでしょうか。少なくとも全文起こすくらいは外でやってもらって、その後の作業を課内でやるというのが、割と役所でもそれが一般的かなと思うので、少しそこを考えていただきたい。できるだけ議論に即した形で出していく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"ごめんなさい。もう一個。すみません。もう一つ気になったのが、先ほど、発言者に対して直接問い合わせがあるというお話がありました。それは、議事録をやんわりする以外に、区としてやっていることがあるのでしょうか。通常、会議の中での発言については、直接発言者ではなくて、まずお問い合わせは事務局という形で、何か工夫されていることがあれば。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、障害者福祉課の事務局といたしましては、個別にお問い合わせをいただかないように返答をしていくです。","voiceIndex":75,"id":"exchange-033"},{"speaker":"渡部委員","kind":"提案","question":"本日結論を出して、不採択でお願いいたします。どういう会議でもそのようなことは起こり得るので、全てがそこに入るということはない。提案と言ったらおかしいけれども、僕は長期基本計画の策定委員をやっていて、同じ出し方をするのです。そのときに、議事録ではなくて議事要旨をホームページに出しているのです。すみません。長くなりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-034"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。こちらの陳情の題目にあります、反対意見の掲載を見送ったという意味ではありませんので、不採択でお願いしたいのですが、情報の公開のあり方はこれからも大切に、丁寧に取り扱っていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-035"},{"speaker":"若林委員","kind":"意見","question":"結論を出すで、不採択で結構です。この陳情者の方は、陳情書にある鍵括弧の部分が大変重要だという主観で陳情を出されていますけれども、区の説明の中で、しっかりとその趣旨も含めながら要旨として区民に公開しているということが十分理解できますので、そのような結論です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。だけど、ここのところにすごく労力をかけて、しかも、このような形で多くの文言を削って要旨だけということになると、伝わるものが伝わらないことにもなってくると思いますので、私はできる限り実際に近い、「てにをは」を直す程度のところで出していくべきではないかと考えています。そのようなところで、情報公開もご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-037"},{"speaker":"あべ委員","kind":"確認","question":"先ほども申し上げましたけれども、委員の確認を得ているということで、手続的に瑕疵があるわけではありません。先ほども申しましたように、理解してもらうためにどういう出し方がいいのか。ただ、エクスキューズとして出すわけではなくて、広く区民の方々に、この議論について理解していただくという目的がありますので、そこのところは、今後もやり方は十分吟味していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"委員長、すみません。１つだけ。申しわけございません。先ほどの私の発言の中で議事要旨のような感じと言ったのは、あくまでも行政が決めることではなくて、独立した委員会ですから、委員長が決めることであります。先ほどは、行政がそうすればというような言い方になってしまったのですが、そういうことです。すみません。申しわけございませんでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-039"}]},{"id":"topic-04","title":"令和元年陳情第６８号 「計画」で需要増を見込み、担い手の確保をうたっている移動支援の従業者養成研修の実施についての陳情","agenda":"令和元年陳情第６８号 「計画」で需要増を見込み、担い手の確保をうたっている移動支援の従業者養成研修の実施についての陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１月１１日の広報に出て、１７日までということで、申込期間が実質１週間しかない。それを３月まで延ばして公募するということになってよかったなと思うのです。この周知というものがすごく大事だなと思うのです。これは、区が品川総合福祉センターに委託する事業と考えていいのでしょうか。区が委託するということであれば、その委託費用は幾らぐらいなのかというところも教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"法人として、自分たちで実施したいという意思が確認できましたので、そのように行っていただく予定です。","voiceIndex":92,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"委託費用は出さないということで、品川総合福祉センターがやるということなのですけれども、この広報を見ると、テキスト代が１,５００円ということで、今までのみらいは５,０００円かかっていました。そういう点で、値段的にもテキスト代しかかからないというところでは、利用料もなくなって受けやすいということで、すごく歓迎すべきことだと思うのですけれども、どうしてそのようになったのかということ。","respondent":"松山障害者福祉課長","answer":"受講料や周知方法等の予定は、第１回目を実施しまして、それ以降、どうやって受講生を集めたらいいのか、あるいは受講生の中でも、実際に移動支援の従事者として実施できる方をどうやって確保したらいいかということも一緒に協議しながら進めていきたいと考えています。","voiceIndex":94,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしますと、需要に対して受け皿がないという状況になっているわけですから、品川総合福祉センターがこれからも継続してやってくれるということで、年間何回ぐらいなのか。区とのかかわりというか、区の方針として、区から助成金を出してさらに進めていくというようなことはないのでしょうかという確認をお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"今後、実施するに当たって、研修を実施する２か月ぐらい前には、必ず東京都に申請を出して承認を得る必要があります。そのため、頻繁にできるわけではございませんけれども、これまでと同じような回数以上はやっていただきたいと考えています。","voiceIndex":96,"id":"exchange-042"},{"speaker":"あべ委員","kind":"質問","question":"品川総合福祉センターが東京都から指定を受けたのはいつだったのでしょうか。","respondent":"松山障害者福祉課長","answer":"品川総合福祉センターが指定を受けたのは、１２月２７日です。","voiceIndex":99,"id":"exchange-043"},{"speaker":"あべ委員","kind":"質問","question":"ごめんなさい。もう一つ、これまでみらいが行っていた案件です。ただ、あの規模で講座を定期的にやるのは少し大変な部分もあったかと思うのですけれども、今回、品川総合福祉センターが、それこそ１,５００円になって、みらいだとどうしても経費がかかるということで、今後、みらいはこの研修についてどうしていくのか。区としては、みらいについてどうされるおつもりですか。","respondent":"松山障害者福祉課長","answer":"区といたしましては、どこの事業所ということではなく、区内全体で多くの事業所の力を借りながら、利用者のサービス向上を図りたいというのが大きな目的ですので、今後もみらいや品川総合福祉センターと協議を進めながら、どうしていくかは詰めていきたいと考えています。","voiceIndex":103,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今回、まずは、品川総合福祉センター独自でということでしたけれども、それ以外にも、やりたいけれども自分の事業所独自ではできないので、少し区の支援があったらなという事業所が出てきた場合は、区に相談して、そのようなことは可能なのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"学則を定めたりといったこともありますので、指定をとるのにかなり大変なご苦労があってとっていただいているです。ただ、実際にやっていきたいという事業者については、ご相談を受け付けておりますので、区としても努力してまいりたいと考えています。","voiceIndex":107,"id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。都の指定を受けまして、品川総合福祉センターが研修を実施できるようになって、本当によかったと思っています。何度か、ほかの委員からもご意見がありますが、周知の工夫の中で、広報、区のホームページ、Ｆａｃｅｂｏｏｋ、Ｔｗｉｔｔｅｒなども活性化されていると思いますので、ぜひ引き続きご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-046"},{"speaker":"若林委員","kind":"確認","question":"結論を出すで、不採択で結構です。品川区も積極的にかかわりながら、都の指定の事業所も誕生した。前に進んでいるということが確認されたので、その結論で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。これが出された時点では、実施の方向が見えないという状況で、それが実際、今回延長されて、３月にされるということになって、本当によかったと思います。この思いが、区としても実施されるということで、さらに今後に向けても充実を求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-048"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、採択でお願いします。本年度も実施するのであれば、理屈の面から言っても、これは採択しないと、今年実施する事業に反対することになってしまうのかなと思われます。今年３月、今年度中に実施されるということに異論はありませんので、採択させてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-049"}]},{"id":"topic-05","title":"令和元年陳情第６９号 障害児相談支援事業所について民間事業所経由で配布された課長名義の文書についての陳情","agenda":"令和元年陳情第６９号 障害児相談支援事業所について民間事業所経由で配布された課長名義の文書についての陳情","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"端的に「はい」か「いいえ」でいいのですけれども、要は、アプリ児童デイサービスが相談事業を始めるから、今まで区で受けていたものをそちらに変えられますよというのを、アプリ児童デイサービスを利用している人に送っただけなのですよね。","respondent":"松山障害者福祉課長","answer":"委員のご発言のとおりです。","voiceIndex":123,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、そこのところなのだと思うのです。そこのところが一般の人というか保護者にはわかりにくいので、そこをきちんと書くようにしていただきたいというのがこの陳情の趣旨だと思うのです。そういう点では、もう少しわかりやすい形での表記が必要ではなかったかなと思いますけれども、その点はどうでしょうか。そのような形の出し方になっているのでしょうか。その点についてもお聞かせください。","respondent":"松山障害者福祉課長","answer":"表記でご不明な点につきましては、陳情者にもきちんと趣旨が伝わるよう、選択できますということはご説明申し上げております。","voiceIndex":126,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、アプリ児童デイサービス利用者の保護者の皆様へ、障害者福祉課から相談支援事業所アプリ北品川に変更されるかどうかについて確認させてくださいという中身になっているので、この方もグローで計画相談を受けたいといったら、グローでもいいわけですよね。実際は、アプリ児童デイサービスに行く方が多いのではないかと思うのです。そこを改めていただきたいということなのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-052"},{"speaker":"あべ委員","kind":"意見","question":"この文章は間違っていないのですけれども、確かに受けとめた方が誤解するかもしれない。陳情というのが妥当かどうかは別として、こういう受けとめ方をされたということは、次に出すときに、今回、間違っていませんと言うよりは、こういう読み方をするのだったら、今度はもう少し変えてみようという感じで活かしていただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-053"},{"speaker":"渡部委員","kind":"確認","question":"先ほど、一番最初に確認したとおりでございまして、そこに該当して通われている児童に、事業所がそういう相談事業を始めるから移りますか、移りませんか。例えば、それを教えてくれなかったら、何で教えないのだと、また倍ぐらい怒られてしまう。そういうことでしっかりやっているわけだから、いいことですし、これからまた相談が増えるということですので、この内容自体は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-054"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほどの課長のご説明で一定の理解を示しましたので、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。区民の方により丁寧にきめ細かくご案内をするということで、そういう取り組みを確認させていただきました。それでも、やはり話していても伝わらないこともあるので、そういうお問い合わせには、引き続きしっかり丁寧に対応していただきたいということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。そこは本当に評価をしているところです。しかし、やはり今までが今までだっただけに、誤解のないようにというところは、注意が必要なのかなと考えています。そういう点では、ぜひ今後とも注意をしながらやっていただきたい。誤解を与えないというところでは、いろいろ工夫もしていただきながら取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-057"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。この文章自体は、不正確とまでは言えないかなと思います。ただ、いろいろな方がいろいろな受けとめ方をされますし、そのご指摘をいただきながら、文書作成の精度、正確さ、わかりやすさは上がっていくと思いますので、こうしたことを一つ一つ活かして、よりわかりやすい文書をつくるようにご対応いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-058"}]},{"id":"topic-06","title":"品川区肺がん検診の契約違反と区の対応","agenda":"品川区肺がん検診の契約違反と区の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１枚しか撮影していなかったことのほうが見つけやすいのではないかなという思いがしたのです。１枚しか撮影していなかったということがわかるような仕組みはないのでしょうかということが１つです。５年１０か月という長い間発覚しなかったというのは、もう少し早くに発覚するような仕組みはなかったのかというところもお聞かせいただきたいと思います。","respondent":"高山健康課長","answer":"当然のことながら、２枚撮影したものを読影した読影医の確認のサインだと私どもはみなしていたものですから、先ほどの説明の中では触れなかった点ではありますが、実際、現代においては、デジタル画像で胸部Ｘ線画像は管理しています。","voiceIndex":144,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから２月に第三者委員会を設置していくということなのですけれども、この第三者委員会の目的や、どのようなメンバーでどんなことをしていくのかというところについてもお聞かせいただきたいと思います。その点についてもお聞かせいただけたらと思います。","respondent":"高山健康課長","answer":"２点目の十分な専門性を有する医師の考え方です。基本的には、検診医療機関は、当然、前提として、臨床として医療を提供されている方々が大半です。当然、そういった医療の提供の場、臨床の場において十分な経験を積んでおられるということが大前提となってまいります。","voiceIndex":146,"id":"exchange-060"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"このＴｈｉｎｋ Ｐａｒｋ消化器クリニックに対しては、どのような対応をされたのでしょうか。何か処分など、区がどこまでなのかわからないですけれども、クリニックに対しての対応を伺いたいと思います。","respondent":"高山健康課長","answer":"この当該クリニックへの対応という点です。区といたしましては、８月を最後に、肺がん検診については既に委託を終了しております。そのほかに、医師会内部として何らかの処分を検討されているといったお話を伺っております。","voiceIndex":148,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":50807,"voices":164}},{"id":"r02-20200120-8","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"建設委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"コミュニティバス導入に向けた検討状況","agenda":"コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それで、間違いないのでしょうかということと、もう少しそのことがわかるように、コミュニティバスの役割のところに明記していただきたい、すべきではないかと思うのですけれども、いかがというところが、まず１点目の質問です。運営方式について、３つ書かれていますけれども、コミュニティバスの運行や導入に際しての国や東京都からの補助金の有無は、現状どうなっているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今ご提案いただいたように、もう少しわかりやすい表現は、まだ骨子案の段階ですので、書き方について検討させていただきたいと思います。補助金のお話ですが、基本的には都の補助がございまして、車両購入費や運行経費の補助金は、都の補助金としています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ですから、積極的にそういうものは活用していただいて、進めていくことが必要だと思います。細かいところなのですが、品川区コミュニティバス導入計画（骨子案）の１ページの、試行運転開始予定時期が黒丸になっているのですけど、今は、書けないということなのか、３回目の検討会には、当然、示されるということなのかを伺いたいと思います。そこら辺もお願いします。","respondent":"鈴木都市計画課長","answer":"しっかり目標を定めて、予定は書いていくのですが、なかなか、そのとおりにいくかというところもあって、今現在は黒丸にさせていただいているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的に言うと、区境で区の公共施設まで遠く、ふだんからコミュニティバスの運行要望をかなり伺う地域が上大崎なのですけれども、その地域を含む大崎第一地域で見ると、今回の指標結果では、３０点台ということで、試行ルート候補の第一候補からは外れているのではないかと思うのです。やはり意見交換会を各地で開いて、計画に反映させるべきだと私は思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"説明会なのですが、前回、第１回検討会の終了後もそうですが、今回、２回目が終了した時点で、ちょうど今、１３地域の町会長会議を回って、第２回検討会の内容をご説明しています。そこでも、いろいろなご意見をいただいてあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを具体化し、運行が始まって、その後、地域、区民の方から、いろいろ要望なども上がってくると思うのですけれども、そういった要望を、ぜひ今後の運行の増便ですとか、あるいは見直しなどに、しっかりと生かしていくような動き方をしていただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"私は、１２月１３日の検討会を傍聴できませんでしたので、この主な発言内容の背景というか、どういう話の流れのときに、こういうご意見が出て、それに対して、何らかの回答というものがあったかと思うのですけれども、その辺のことを伺いたいと思います。その辺について、今、時点のお考えなどを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"第１回検討会後に１３地域を回り、今、第２回検討会後の説明に回っているところですが、やはり、１回目のときは、いろいろ現状をお示ししましたので、地域それぞれでとったアンケートでもいただいておりますが、具体的にここから、ここに走らせていただきたいとか。","voiceIndex":13,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"ありがとうございました。地域のご意見を伺うのは、基本的には町会長の皆さんという感じなのでしょうか。その辺は、もう少し地域の方に広げて意見を聞くような場を設定する、おつもりはないのかを伺います。","respondent":"鈴木都市計画課長","answer":"今のところは、３回目までは、こういう形で進めさせていただいて、この基本方針も、しっかりパブコメをかけますし、ルートをさらに具体的に決めていくときには、この町会長会議だけではなくて、地域の方に集まっていただいて、ご意見をいろいろいただきながら。","voiceIndex":15,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。だから、住民の声はぜひ聞いていただきたいのですけど、やはり、住民同士が違う地域の人たちの意見も聞いて、住民全体のルート選定の納得度を高めるという作業が必要ではないかと思いますので、その辺は、ぜひご検討をいただきたいと思います。一度走らせたら、必ずそことは限らないような柔軟性のある試行にしていただきたい。これは、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"松本委員","kind":"提案","question":"１点だけ。別紙２の８ページに事業者提案に対する条件の項目例がお示しいただいています。これは、第３回検討会で、提示予定ということなので、それまでに、そのあたりもご検討いただければなと思います。そういう環境などを、提案の条件に入れていただく。こういう動きもお願いできればと思うのですが、現状、そのあたりの検討状況はどうでしょうか。","respondent":"鈴木都市計画課長","answer":"当然ながら、誰にでも乗っていただけるようにということですから、そうした点も大事にしながら、提案項目はしっかり検討していきたいと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"８ページの表５です。運行事業者の選定方法として、３つの方式が示されています。これも次回という話だったかと思うのですが、それについては、この検討会の中で、ご意見をいただいて、決めていくのでしょうけれども、区のほうで、方向性を一定程度示すのか、それとも、全くノープランで、この３つの中から委員のご意見を聞いて、決めるのかを教えてください。","respondent":"鈴木都市計画課長","answer":"運営方式の３パターンです。第３回検討会では、一定程度、区としての考えをお示しして、何も示さず、意見をいただき、その場で決めるというよりも、区ではこう考えますがというところはお示しして、ご議論をいただくと考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。２点目の地域をまたがるという話です。そういうところも踏まえて、できる限り、走らせたいけれども、すべては無理があるわけですから、限りがある中で、ここだったら、歩いて、一、二分のところに、どこどこ行きのバスに乗れるということも考えられると思うのですが、一応そこはお願いしたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ルート選定にあたっては、国のほうから、指針として、民間のルートとの競合は避けてくれということは明確に出ていますので、そこはしっかり押さえながら、乗り継ぎについては、先ほどの視点の中に入っておりませんでしたが、当然ながらそうした視点も入れながら。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"（仮称）品川区水辺利活用ビジョン（素案）","agenda":"（仮称）品川区水辺利活用ビジョン（素案）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は、こういった活動にかなり力を入れていますので、じかに住民の前で説明までするような説明会を開いた上で、やはりパブリックコメントをやるべきなのではないかと思うのですけれども、そこに関してはいかがでしょうか。目黒川で、水辺活用というならば、この改善は必要な点なのではないかと思うのですけれども、その記述がない理由は、なぜなのかを伺いたいと思います。","respondent":"鈴木都市計画課長、松本河川下水道課長","answer":"基本的には、今、パブリックコメントをもって、この計画、ビジョンに対する区民の方のご意見をいただいて、取りまとめに反映をしていきたいと考えていますので、全体で説明会をする予定はございません。品川区といたしましても、年間１度ですが、河川のしゅんせつを行っているところです。引き続き、上流区の世田谷区、目黒区とも連携して、水質改善に向けて、いろいろな取り組みをしていきたいと考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした大きなビジョンのパブリックコメントでは、ぜひ、まずやってみる、踏み出していくということをやっていただきたいと改めてお願いします。水に親しむということであれば、もう少し改善が必要なのではないかという率直な区民感情があると思いますので、伺いました。区として、どこまで、こうした水辺の利活用に関して、財政投入をしていこうという考えなのかについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１つ言えることは、区としては、積極的に水辺をしっかり活用していく取り組みを進めていきたいというところは言えると思うのですが、全ての費用を投入して、やっていくということではなくて、それぞれの立場が、それぞれの役割に応じて、協力しながら。","voiceIndex":33,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"水質改善というと、東京都や品川区に求めてしまうのですが、実は、水質改善には、地域に暮らす人たちの生活が直結しているのです。そこへの発信が、私の見る限りでは、東京都の発信のほうが強い。いつまでに、どういうという、余り具体的な計画ではないとおっしゃいましたけど、何か地域住民や事業者等にその理解を深めていく、各自、取り組みをしようという発信のお考えがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたところを、いろいろな場面で、地域の方に見ていただいて、取り組み、あるいは意識を持っていただく。そうしたところを、今後しっかり考えていきたいというところの第一歩として、書かせていただいているところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"環境計画の中に、私たちの意見を少しだけ取り入れていただいたようなところがあるのですが、私は、決算特別委員会や予算特別委員会の質問の中でも、こういう合流改善への具体的な取り組みを求めております。この辺のことはビジョンではありますけれども、やはり、ビジョンは、これから目指すということですから、ぜひ、優先順位というか、政策的な順位をもう少し上げていっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"水辺の利活用に向けて、こういう計画をよろしくお願いしたいと思います。今の話があったから、３つぐらいになるかもしれません。もう１点は、天王洲エリアは構わないのだけれども、もう少し品川浦に触れてほしい。品川浦と天王洲は少し違うから、同じ一括りになっているのだけれども、水辺を語るときに、それも１つお願いしたい。どうせここまで書くなら、水面活用も書いてほしかったと思います。","respondent":"鈴木都市計画課長","answer":"パブリックコメントとあわせて、反映できるところは、しっかり水面の活用も含めて検討し、充実して、最後に取りまとめていきたいと考えています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"今の石田秀男委員の目黒川のところです。そう考えると、根本的に水辺などの流れる形状を変える。高度経済成長のときに形づけられた川の形状でしょうか。運河の形状は、あくまでも経済効率優先で、形づくられた、設計されたものなので、観光と相なじまない形状になっているのではないかと思うのですけれども、そこのところは、どういうふうに捉えていらっしゃいますか。","respondent":"鈴木都市計画課長","answer":"そうしたところを振り返って、ただ、今現在の品川区としての水辺の利活用を考えているときは、やはり、親しんでいただいて、街に来ていただいて、いかに水辺を楽しんでいただくかです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"目黒川は、両方とも囲まれていて、とても生きている川とは、私は思わない。やはり、命の息吹を、１つの川に吹き込むということは、並大抵のことではできないわけで、川の形状、周りを、ある程度、変えてしまうぐらいの意気込みをもって、この問題に取り組んでいただきたいと思うのですけれども、ご感想をお聞かせください。","respondent":"鈴木都市計画課長","answer":"そうした中で、どこまで、今の河川の形状を変えてというところを書けるか、どうかということは検討していきます。ただ、ご提案いただいたように、夢が現実的になっていくように、大きい視点でも書かせていただきたいです。","voiceIndex":42,"id":"exchange-017"}]},{"id":"topic-03","title":"住宅補修緊急支援事業の実施","agenda":"住宅補修緊急支援事業の実施","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"ご説明がありがとうございました。確認なのですけれども、例えば、区で上乗せしない場合には、都の１５万円の補助金は使えないのか、あと、対象となる補修工事費の２分の１となっているのですけれども、東京都の１５万円も、この２分の１という条件がついているのかどうかということです。その辺をお伺いします。","respondent":"森住宅課長","answer":"返事がない、あるいは郵送した後に見逃されているということがあるかもです。本日、発送の作業をしておるところでございまして、その後、向こうからの何かしらのアクションがなければ、ご提案のあったようなことも考えながら、しっかりと周知をしていきたいと思っています。","voiceIndex":51,"id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問","question":"ぜひよろしくお願いします。今の１点目のほうです。都が１５万円を出すことも、品川区では、３０万円もしくは対象となる補修工事費の２分の１の低いほうとなっていますけれども、例えば、１０万円かかった場合、２分の１なので、５万円になると思います。都でも、この２分の１という条件はついているのでしょうか。","respondent":"森住宅課長","answer":"東京都のほうも、２分の１までと、あるいは、１５万円以内のどちらか低いほうという形になってあります。要するに、今、言われた１０万円ということになれば、５万円が補助金になりまして、２万５,０００円ずつ、都と区が出すという形になります。","voiceIndex":53,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"被害を受けて、補修をした、でも、り災証明を取得していなかったという方は、どうなるのか。そういった方は、資料にある一部損壊認定の８３件には含まれていないのでしょうか。伺います。","respondent":"森住宅課長","answer":"今回の事業につきましては、り災証明の発行が必要になってまいりますので、それについて、改めて地域センターで、申請をしていただいて、建築課の職員等が伺って、今、直されたということであれば、例えば、領収書や、以前の写真を確認しながら、り災証明を発行し、その後。","voiceIndex":55,"id":"exchange-020"}]},{"id":"topic-04","title":"武蔵小山駅周辺地域のまちづくり","agenda":"武蔵小山駅周辺地域のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この再生方針の地区指定を東京都に依頼して、認可がされたということです。その観点から、お伺いしたいことは、３番目の小山三丁目第１地区のところの面積要件です。賛成している方々、準備組合に加入して、この計画に賛成している方々の面積でも、３分の２以上をとらないと、進められなくなるのですが、そこの面積要件という点では、どのようになっているのかということをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"都市再開発法上で、３分の２というところはありますが、丁寧な説明をやりながら、後々も、この街がより発展していくためには、この開発段階での皆さんの合意をしっかりとっていくことが非常にいいことだと考えておりますので、そういう考えのもと、進めております。","voiceIndex":61,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"準備組合に加入している方も、加入しないと、情報が来ないという意味で入っている人もたくさんいますので、７７.０７％と８３.４９％ということですが、まだまだ合意ができているとは言いがたい状況なのではないかと予測しますし、実際に、相談などでも、いかがなものかという立場からの声なども伺います。","respondent":"小林環境課長","answer":"この手続きに関する内容につきましては、東京都の制度を用いて進められることでございまして、その制度の中身からいきますと、恐らく、委員がお話しになっているような説明会というところにつきましては、環境影響評価書（案）の段階か次の段階だと考えています。","voiceIndex":63,"id":"exchange-022"}]},{"id":"topic-05","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"毎年、大体、何人ぐらい、当日は参加があるものなのかということと、参加すればいいのですけれども、環境保全活動顕彰の２部門、６件について、どのような活動だったのかということを知りたいので、主なものでいいですけれども、ご紹介していただければと思います。","respondent":"小林環境課長","answer":"例えば、地域部門のほうですと、八潮自治会連合会環境維持改善部ですと、大井ふ頭の緑道公園、京浜運河などの非常に幅広い範囲での清掃活動を、月１回、継続的に行っているというところとあわせて、地域の方だけではなくて、近接の地域の方や高校生ボランティアを募るなど。","voiceIndex":69,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"今のご質問の続きのような感じになるのですけれども、こういった賞をそれぞれ選ぶ基準は、どのようなところで審査されているのか。地球温暖化防止活動ということがありますけれども、近年、具体的な環境課題が、また、いろいろ出てきていて、特に最近では、海洋プラスチックの問題です。新しい環境課題が生まれてきたときに、選定の際、そういう視点を入れられているのか、その辺について伺いたいと思います。","respondent":"小林環境課長","answer":"この環境保全活動顕彰ですが、これは実施要項に基づきまして、取り組んでいるところです。その中で選ぶ基準としては、例えば、発展性や独自性、地域貢献性、活動頻度といった項目を、選考基準として選ばせていただきまして、選定委員会を置き、選定したものです。","voiceIndex":71,"id":"exchange-024"}]},{"id":"topic-06","title":"武蔵小山駅放置禁止区域の変更","agenda":"武蔵小山駅放置禁止区域の変更","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"再開発に伴う７５１台（店舗用２５１台を含む）とは、どういう意味なのか。店舗用は、別にきちんとあって、残りは何なのかを説明してください。","respondent":"古郡交通安全担当課長","answer":"これについては、７５１台のうち、店舗用として２５１台、そのほかに５００台が、公共的に用意されたものでございまして、定期利用と当日利用となっております。","voiceIndex":77,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるようで、なかなか、ないと思うので、そこら辺をもう少し説明していただきたい。ですから、ある意味、今までは、暗黙の了解的に、ここが商店街の駐輪場みたいな感じの位置づけになっているのではないかという印象がありました。商店街の中原街道寄りのほうに、お買い物に来ている方々の自転車は、どこにとめればいいのかについて、区はどういう考えをお持ちなのかをお伺いします。","respondent":"稲田都市開発課長、古郡交通安全担当課長","answer":"一般の一時利用は、９０分までは無料で、以降、２時間で１００円ずつかかるという状況です。１時間半、無料になっておりますので、こちらを、しっかりと利用していただいて、道路に放置しないようにしていただきたいと考えております。","voiceIndex":79,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ですから、４月１日ということで、まだ先ではありますが、合意形成が大丈夫かという心配があるのですけれども、拙速なのではという印象もあります。商店街の方とはよく話し合って、進めてきているとは思うのですが、よく話し合って、結論を出すべきだと思いますが、そちらについてのこれまでの進め方、これからの進め方などについて、お考えはいかがでしょうか。","respondent":"古郡交通安全担当課長","answer":"これを指定する際に、地元の町会ですとか、商店街の方々に意見を聞きまして、こういったことで決定していくです。ですので、地元の了解と商店街の了解を得ていると認識をしています。","voiceIndex":82,"id":"exchange-027"}]},{"id":"topic-07","title":"品川区無電柱化推進計画（素案）","agenda":"品川区無電柱化推進計画（素案）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"何回も言って、恐縮なのですが、パブリックコメントの際には、説明会の実施をセットにして、行っていただきたいと思います。無電柱化の現状ですけれども、無電柱化の課題はあるのですが、無電柱化そのものは、何かデメリットみたいなものはあるのでしょうか。そちらについてお伺いしたいと思います。","respondent":"多並道路課長","answer":"説明会の開催についてですけれども、今回の推進計画の素案を定める際には、パブリックコメントという形で、広く区民の方にお示しして、ご意見をお伺いしたいと考えています。今度の新しい推進計画の中には、そのご意見を反映してまいりたいと考えています。","voiceIndex":89,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、いつなのかということは課題があると思います。こちらも、地中化の要望なども伺ったことがあるのですけれども、こちらは、技術的に無電柱化は可能でしょうか。今回、検討対象になったのか、その結果、入らなかったのか、可能であれば、候補に入れていくことも必要なのではないかと思いますけれども、いかがでしょうか。","respondent":"多並道路課長","answer":"そういう技術の状況を聞きながら、また、今後、推進計画を定める際には、基本的には、この６路線を中心としながら、今のように、ご提案があった路線は、また、いろいろご意見をお伺いしながら、改めて計画を見直す際には、考えていきたい。そのように考えているところです。","voiceIndex":91,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"意見","question":"ほかの1)から3)は、普通の道路、区道なので、ないと思いますけれども、もちろん4)も区のほうの計画になるので、地元のそういう負担はないのかということと、一方で、先ほど言ったように、商店街なので、いろいろな商店街としての景観等に資するようなものをやりたいという場合に、話し合いの余地があって、なおかつ、その場合には、負担が出るなど、その辺の細かいところはあれなのですけれども。","respondent":"多並道路課長","answer":"ここに関しては、区の道路課だけではなくて、商店街の関係なので、商業・ものづくり課、また、景観の部署など、いろいろな部署と連携を図りながら、実際の工事をやる段階では、地元も含めて、検討していきたいと思っているところです。","voiceIndex":93,"id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問","question":"一緒に聞けば、よかったのですけど、図を見ると、踏切を越えてはいないけれども、やはり、考えとしては、踏切を越えてということは考えなかったのか。もし、その辺の理由がわかれば教えてください。","respondent":"多並道路課長","answer":"もともと、駅の改札から病院までの間のバリアフリー化の計画がベースとなっていますので、実際に災害があった際の駅と緊急拠点病院との間ということで、踏切よりも中原街道側、要するに、踏切は入らない計画としています。","voiceIndex":95,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後、補助金の話も出ているけれども、そういうところも考えて、設計をしていこうと考えていらっしゃるのかということが１つ。もう１点は、例えば北品川の旧東海道は、やはり、店舗があるので、夜間工事をした。例えば、昼間にやれば、こういう期間で済みますという２つの案を出すなど、そういうことも含めて、地域と話すのかというところだけお聞かせ願いたいと思います。","respondent":"多並道路課長","answer":"石畳等の地元の負担の件ですけれども、今、委員にお話しいただいたように、今まで整備した内容でありましたら、地元のご負担もありましたので、今後の整備についても、基本的にはそういう考えなのですが、ただ、こういう制度はいろいろ動きがありますので。","voiceIndex":97,"id":"exchange-032"}]},{"id":"topic-08","title":"オリンピック・パラリンピック施設周辺道路 遮熱性舗装工事","agenda":"オリンピック・パラリンピック施設周辺道路 遮熱性舗装工事","exchanges":[{"speaker":"松本委員","kind":"意見","question":"遮熱性舗装ですけれども、たしか、路面の温度は下げるけれども、周辺の気温は上がるという報道があったかと思います。こういう報道が出たのが、去年の秋ごろで、その後、何か対策というか、検証がなされたのかというところをお願いいたします。","respondent":"多並道路課長","answer":"令和元年８月ぐらいの新聞報道だったかと思います。ちょうどランナーが走るコースにおいて、反射した赤外線で、暑くなるのではないかという報道があったかと思います。","voiceIndex":103,"id":"exchange-033"}]},{"id":"topic-09","title":"防犯カメラ設置工事","agenda":"防犯カメラ設置工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"安全・安心な街をという願いは、すごく大切なことだと考えています。そもそも、全ての公園への防犯カメラ設置へ踏み切った理由は何なのかを伺います。設置が必要となる事象が具体的に増えてきているということなのか、また、それだけの要望が、区民から上がっていたということなのかを伺いたいと思います。","respondent":"溝口公園課長","answer":"人的対応だけでは、なかなかやり切れない地域の安心・安全も、公園管理者として、しっかり守っていきたいといった思いがありまして、全ての公園に、防犯カメラを設置していくとしたものです。","voiceIndex":109,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"犯罪抑止効果という期待の一方で、監視社会なのではないか、個人情報の流出の心配ですとか、そういうものがあるわけですけれども、この映像の情報がどのように管理されて、その運用や提供のルールなどは、誰が、どう定めて、実際のルールの内容はどうなっているのかという概要を伺いたいと思います。","respondent":"溝口公園課長","answer":"今回、防犯カメラ設置にあたりまして、管理および運用に関する要綱を、区長決定で定めているものです。この中では、個人情報の保護を、または、設置する際には、近隣の方へのプライバシーの配慮といったものも盛り込んでおりますので、この要綱に基づいて、運用するものです。","voiceIndex":111,"id":"exchange-035"},{"speaker":"安藤委員","kind":"意見","question":"くれぐれも目的を逸脱した情報の提供などが行われることがないように、ないと思いますけれども、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"犯罪の未然防止は、誰でも願うところだと思うのですけれども、今現在、防犯カメラの映像が使われるということは、犯罪が起きた後、犯人を特定して、逮捕するということが、次の未然防止につながるというご趣旨だということはわかります。ぜひ、多くの人たちの目につくようなところに、防犯カメラが作動しているということが書かれているほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"ただ、公園の中は、禁止事項が多いと言われているところです。そういった公園の利用者の方の声も聞きながら、全体的にどのような形で周知していくのかは、引き続き、管理状況等を見ながら、考えていきたいと考えているところです。","voiceIndex":114,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ制約があることは了解しておりますけれども、でも、これを防犯カメラということで広げていくということであれば、ぜひ、本当に抑止のほうに律するような方向で検討していただきたいと思います。これは、意見にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-038"}]},{"id":"topic-10","title":"廃棄すべき備蓄物資（紙おむつ等）の転売事案","agenda":"廃棄すべき備蓄物資（紙おむつ等）の転売事案","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"この件につきまして、いろいろ問題があると思います。報道の後、区民からのお問い合わせもありましたので、防災課長に話を伺いました。この契約書を情報公開請求で取り寄せましたが、この仕様書で、どれくらいの間、こういうことが行われていたのかを把握していらしたら、教えていただきたい。","respondent":"中島防災課長","answer":"契約の経過としては、主にこのような形の物品供給契約をしてきたところですが、どのぐらいの件数でありますとか、いつからというところについては、私のほうでは把握しておりません。基本的には物品供給契約の中で、備蓄物資の購入等を行ってきたです。","voiceIndex":121,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"物品供給契約ということで、この間ご説明を受けたときには、そういうことなので、廃棄については、マニフェストなども義務づけていないというお話でした。私も、前回の決算特別委員会で、契約のあり方について、総括質疑を行ったものですから、その契約のあり方として、どうなのかということで、先ほども言いましたけど、情報公開請求で、契約書を求めました。","respondent":"中島防災課長","answer":"委員ご指摘のとおり、今回、仕様書の中には、回収したものを適法に廃棄をするということで、記載はあったのですけれども、その具体的なところが示されていなかったというところもありますので、基本的には廃棄をしないことを第１としていきますが。","voiceIndex":123,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"今後については、まずは捨てない方向でという結論については、私たちもとても賛成です。ただ、今までこういう契約がずっと行われていたということに関しては、この紙おむつのことだけではなくて、見直していただきたいと思います。現実的に報告がどうだったのかということと、こういうような契約がほかにもあるのではないかと思ってしまうわけですが、その辺の見直しについて見解を伺いたいと思います。","respondent":"中島防災課長","answer":"そこについては、徹底してまいりたいと考えています。","voiceIndex":125,"id":"exchange-041"}]},{"id":"topic-11","title":"令和元年度品川区地域防災計画の修正","agenda":"令和元年度品川区地域防災計画の修正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"避難所、避難場所、自主避難施設の定義を明確にすると書いてあるのですが、実際、どういう定義になるのかということが、これだけではわからないので、ご説明いただけますでしょうか。今回、この点では、どのようなルールが定められるのかを伺いたいということが、１点目です。今回、修正項目の(1)のイのところに書いていますので、そこら辺は、今回の修正では、どうなったのかを伺います。","respondent":"中島防災課長","answer":"あくまで、区の職員が開設、運営するというところの記載で、運用につきましては、適宜、区のほうで、また対応してまいりたいと考えております。最後に、ハザードマップと区の避難所の関係です。","voiceIndex":133,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"(6)運用については、適宜、対応していくということですとか、最後のところは、計画で定めるものではないということです。それを踏まえた上で、そういった事態をどう改善していくかという点で、改善が求められるわけですけれども、今回の修正とは、また違う場面であるというのであれば、どういったところで、そういった修正を具体的にされていくのかを伺いたいと思います。","respondent":"中島防災課長、曽田災害対策担当部長","answer":"そこにどのように記載していくかというところにつきましては、具体的なところに、記述できるところは、記述してまいりたいとは思っておりますが、個別の書き方というところについては、今後、検討課題という形になるかと考えています。少し時間をかけて、こういったことを検討をして、今回の地域防災計画には反映できませんけれども、来年度の地域防災計画の修正など、あるいは、急ぐものについては、次の出水期までには、何とかできるものはやって。","voiceIndex":135,"id":"exchange-043"}]},{"id":"topic-12","title":"品川区国民保護計画の変更","agenda":"品川区国民保護計画の変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、変更ということなのですけれども、平成２４年度に計画が変更されて、その後７年が経過しているというところです。平成１９年に計画策定、その後、平成２７年９月に、いわゆる安保法制が成立したのですが、変更目的に、「この間、国の基本方針や都の計画が変更されており、整合を図ることを目的に変更する」とあります。それとも、関連性が余りないのかについて伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"区の国民保護計画の作成もしくは変更の流れですが、国民保護法に基づきまして、まず、国が基本指針を作成しております。この国の基本指針は、おおむね２年に１回ぐらい、細かな修正がかけられておりまして、その状況を見まして、東京都の計画が変更されております。","voiceIndex":143,"id":"exchange-044"}]},{"id":"topic-13","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"確認後にすいません。字句の修正は、個別に申し上げればよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":60069,"voices":159}},{"id":"r02-20200120-9","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"文教委員会","time":"午後 １時００分～午後 ４時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和２年度新入学の学校選択希望申請理由調査結果","agenda":"令和２年度新入学の学校選択希望申請理由調査結果","exchanges":[{"speaker":"横山委員","kind":"質問","question":"回収率なのですけれども、昨年よりも少しだけですが下がっているようなのですが、その辺りを教育委員会としてどのように捉えていらっしゃるのか、教えてください。昨年、この結果が得られていたと思うのですけれども、この１年で学校運営の改善というところにはどのようにつながっていて、今回についてはこれから活かしていくということになるかと思うのですけれども、その辺りの状況を教えてください。","respondent":"篠田学務課長","answer":"こちらは例年、８０％を超えるような形ではいただいているのですけれども、極端に変化することはあまりないのですが、任意ですので、必ずしもこちらを出していただくことと、希望選択が結びつくものではないと説明をさせていただいているので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"希望申請理由調査の改善点のところでは、今は具体的にはなっていないという回答だったのですが、教育委員会でつかんでいる、実際、その学校でどのように改善をしたというものがありましたら、教えていただければと思います。そこについては、もちろん受入れをしていくということになると思うのですが、どういった対応になっていくのか、教室の関係ですとか、そういった点を伺いたいと思います。","respondent":"篠田学務課長","answer":"受入れ枠は３クラスで１０５名になっていますけれども、こちらは７年生ですので、原則は１クラス４０名、この場合は３クラスですと１２０名までとれるということになりますので、この受入れは無抽選の方が一定程度抜ければ、対応ができるものと考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"希望申請の理由ですが、今のところ教育委員会はフォローできていないということなのですけれども、そうすると、どう活かされているかというのは教育委員会ではつかまれていないということになるのか、そこのところを、改めて確認になってしまいますが、伺いたいと思います。小学校では、１番目に「学校の教育活動に魅力がある」と。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"フォローの件ですけれども、どの校長も当然、自分の学校でお子さん方を受け入れるにあたって、保護者、お子様が、どういったことを重視して選んでいるのかというのは、気にしていますから、毎年同じような傾向であるとはいえ。いずれの学校においても共通するところかと思いますけれども、やはり教育活動に魅力があるというのは、どの学校も上位になっていますので、特に学校によって格差はないと考えておりますが、各校とも自分の学校の特色ある内容を。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校間格差はないということでしたけれども、新しい校舎とか、そういったところで選択するということになってしまうと、環境整備というか、施設の問題になってしまうので、そういったところではないというお話で、地域にあるよさ、商店街が近いとか、そういったところを活かしたもので、公教育として、義務教育として、場所によって学習内容、得られるものに違いがないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"塚本委員","kind":"確認","question":"１７名以上、この学区内の人がどこかから入れざるを得なくて増えるということは、急遽の転入は別ですけれども、そういうものとして見ればいいのかというのを確認の上で、さっきの説明で私も聞きもらしたのか、よくわからなかったのですけれども、戸越台中学校が無抽選７８名で、戻りがどこにも書いていないのですけれども、よその学校でも戻りが書いていないところがありますが。","respondent":"篠田学務課長","answer":"ですので、今年も一部の学校では、春に受け入れができるように、足りなくなってもすぐに対応できるような形での工事を何校かで行っております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。それで、特に小学校の待機とかについてなのですけれども、第１位待機は兄弟枠、そして第２位が隣接する通学区域、第３位が旧ブロックということで、それぞれ待機が出ている。率直に言えば、３クラスであれば１０５人までは、まず受け入れるものだという前提で進めるのか、そうではないのかというところですけれども、その部分をお話しいただきたいと思います。","respondent":"篠田学務課長","answer":"そういったことでできるだけ柔軟に、希望された方をお受けするような対応はこれまでもとってありますので、今年度に関してもそういったことで進めてまいりたいと考えているところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"１クラス３５人と考えたら、転入とかがなければ、かなり余裕がある場合があるわけです。そのときに、３５人まで受け入れられるのであれば、待機している人は１０５人になるまで受け入れましょうという考え方というのは、とっているのか、とっていないのか、そこを。","respondent":"篠田学務課長","answer":"実際に４月の入学の近くまで判断が引っ張れるのであれば、そういった考え方もできるかと思うのですけれども、小学校に関しましては今月末までという形になりますので、残り２月・３月の期間というのが、どうしても住基の移動の多い時期になりますので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。本当は、せめて兄弟枠は全部待機なしでという思いはありますけれども、せめてそこは、本来の３５人というクラスの定員の中で受け入れられたのに、という思いがないような形での運用というか、措置というか、そういうものを何とか考えていただきたいというか、対応をできる限りしていただきたいと思いますので、そこは要望として、終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"アンケートのほうで、これは全体の大きな数字だと思うのですけれども、各学校で独自に、選択されたお子さんたちに対して、全くこれと同じでも構いませんけれども、学校ごとのアンケートの形式でとっていらっしゃるのかということです。もしやっていないとすると、なぜやらないのかということをお伺いします。","respondent":"篠田学務課長","answer":"基本的には各学校によって、それぞれ考え方がありますので、取り組みをされているかどうか、必ずしも全部は把握しているものではございませんけれども、学校ごとに独自のアンケートをとっているという話はあまり聞かないので、基本的には教育委員会でとった。","voiceIndex":23,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"どこもやっていない可能性が高いという前提で、またお伺いします。学校ごとの特色を出すために、皆さんが努力されていらっしゃるので。その点についてはいかがでしょうか。教育委員会のほうからやりなさいと言ってくださいという意味ではなく、学校ごとにそういうのをやったほうがいいと思うのですけれども、その点はどうでしょうか。","respondent":"大関教育総合支援センター長","answer":"今回、ご提案いただいた内容は、参考にして、学務課、教育総合支援センターともに、今後のあり方、有効な内容については、また検討を進めたいと思います。","voiceIndex":25,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"確認","question":"抽選校の話ですけれども、今、兄弟が待機しているということは、ご本人や保護者の方は大変つらい状況だと思うので、先ほど塚本委員からお話があったように、許す限りのところでやっていく状況をお願いしたいというのは同じ意見なのですが、改めてもう一度、できるだけ柔軟性をもってと最後に塚本委員のお話にありましたけれども、その辺りについてもう一回確認したいです。","respondent":"篠田学務課長","answer":"これは実際に受入れる校長の考え方等もありますので、私どもはこれで何とかいけるのではないかと思っても、なかなか学校の事情で、そこまで今の時点では判断が難しいということなど、実はこの時期になると、いろいろなせめぎ合いがあったりするのですけれども。","voiceIndex":27,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"中学校のほうは、これは待機していますけれども、かなり私立に行くので、中学校のほうは事実上、希望が通らないというお子さんは小学校よりも少ないと思うのですが、制度自体の当初との乖離が出てきている部分で、選択しても入れない方が、小学校は４分の３が待機しているわけですから、そういったことについて、現状、その仕組み自体。","respondent":"篠田学務課長","answer":"現状はできるだけきちんとした形でお子さんを受け入れながら、どれだけ学校選択したお子さんも対応できるかということで、正直、なかなか基本の部分が変わらないと難しいところではあるのですけれども、いずれにしても、学校選択ができるということ自体が。","voiceIndex":29,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"提案","question":"私もどうすればいいという明確な改善方法というのも、いろいろと絡み合っているところで、なかなか提案できないので、そこは大変恥ずかしいところではあるのですが、ただ、今後、今のお話にあったような形で課題もあるわけですから、それを改善するように、また私も勉強させていただいて、提案していければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"１点だけお伺いしたいのですが。私が不勉強で申しわけないのですけれども。そもそも抽選になっている兄弟枠というのは、上のご兄弟も学区外ということになると思うのですけれども、そういった方は、例えば転居とか、そういった理由が多いのでしょうか。なぜ上のご兄弟も学校を選ばれているのかというか、どういった状況が多いのかなと思いまして。すみません、教えてください。","respondent":"篠田学務課長","answer":"転居の話もございましたけれども、当初はその通学区域内にお住まいだった方が、ほかの学区域に転居された場合にも、当然、ご兄弟の下のお子さんが入学される時点では学区外となってしまいますので、これも兄弟枠という形での対応になってくるというものです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"私の周りでは、上のお子さんが障害児で、特別支援学級に通っていて、特別支援学級の学区も普通学級と別ですので、例えば上のお子さんが第一日野小学校の特別支援学級に通っていて、下のお子さんは第一日野小学校の学区ではないということもあると思うのですけれども、そういったことは今までどういう対応になっていたのでしょうか。","respondent":"大関教育総合支援センター長","answer":"就学相談は、特別支援学級を選択されるお子さんの部分だけで対応していますので、その下のお子さんに関しては、通常の学校選択制の中でまず行っていただいて、その後、指定校変更等の相談が叶うかどうか、全体の状況を見ながらとなります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"せお委員","kind":"確認","question":"状況を確認したく、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"確認","question":"先ほど言い忘れてしまったのですけれども。今、特別支援学級の話が出たのですが、特別支援学級の学区は別にあるということでホームページにも出たりしているのですが、一つ確認で、それも必ずしもそこの学区ではなく、就学相談やいろいろな相談から別の学区の特別支援学級に入学することが可能であるという、そこは相談の中で十分対応していただけるということでしょうかという確認です。","respondent":"大関教育総合支援センター長","answer":"個別に就学相談を進めながら、障害の特性等から、例えば、本来でしたら豊葉の杜学園を選ばれる地域ですけれども、浅間台小学校のほうを選びたいというような相談を受けるケースには柔軟に対応しています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、柔軟にというお話を伺ったので、ぜひ個別に保護者の方と十分に話し合って、進めていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"}]},{"id":"topic-02","title":"児童相談体制の強化","agenda":"児童相談体制の強化","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"協定の締結ですが、今回、警察と情報共有していくということで、具体的にはどういった運用といいますか、実際の形がイメージできるようにご説明いただけたらと思います。それがいいのか悪いのかについてもあると思うのですが、そこのところと、そういった奥まった場所になった経緯などを伺えればと思います。","respondent":"崎村児童相談担当課長","answer":"分室についてなのですけれども、昨年４月に一時的に移転をした後、やはり今後職員が増えていくというところで、どこかへ移転をしなければならないということで、経理課等と検討してきたところです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"分室のほうは、ぜひしっかりと周知をしていただいて、入ってすぐのところなので、見ればわかるかもしれませんが、きちんとわかりやすいようにしていただきたいと思いますし、今後、職員の増が見込まれるということで、今、実際に、児童相談担当、児童相談所移管担当の職員の方が何人いて、今後何人になるという見込みというのがあると思うのですけれども、それを伺いたいと思います。","respondent":"崎村児童相談担当課長","answer":"今後の職員の増員の見込みなのですけれども、まだまだ児童相談所の開設に向けては、児童福祉司、児童心理司の候補が足りないといったところで、順次採用をしながら育成をしていくといったところで、その年度ごとに何名の職員が児童相談担当に配置されるか。","voiceIndex":52,"id":"exchange-020"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、今後増えていくところで、分室は、スペース的には十分確保できるということでよろしいのですよね。確認を。","respondent":"崎村児童相談担当課長","answer":"今回、約４４０m2の物件に移転するというところで、事務室も相当確保しておりますので、今後、職員が複数名増えても対応できると考えております。","voiceIndex":54,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"１点だけ。繰り返しになってしまうところもあるのですけれども。そういった引き継ぎ等、今後、発生することを含めて、現在の移転先のスペースに関して、今、どのように考えていらっしゃるのか教えてください。","respondent":"崎村児童相談担当課長","answer":"この会議室というのが、月１回行われる児童虐待防止会議ですとか、虐待ケースの進行管理会議に活用する予定なのですけれども、かなり広くとっておりますので、職員数が増えた場合に、会議室を一部転用させていただいて事務室にするとか。","voiceIndex":57,"id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"東京湾岸警察署が品川区を管轄しているというのが意外だったのですけれども。確認なのですが、これは東八潮に東京湾岸警察署があるから、そうなったのかということと、あと、事務室が移転される分室の建物なのですけれども、建物は築何年というか、もともと何年前からあったものだったのでしょうか。２点お伺いします。","respondent":"崎村児童相談担当課長","answer":"このリースが１年ちょっと使われていたと聞いておりますので、それをそのまま我々のほうでお借りいたしまして、今回、使用するというものです。","voiceIndex":61,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"ということは、マンションギャラリーで使われていた建物を、基本的にそのまま居抜きみたいな形で使うというイメージでよろしいのでしょうか。一部手直しとかもされる予定なのでしょうか。","respondent":"崎村児童相談担当課長","answer":"マンションギャラリーとして使用されておりましたので、私も最初に中を見せていただいたところ、１階部分が商談スペースのような、商談用の小さい会議室というようなものと、あとは２階部分については、住宅仕様が２部屋ありましたので、その中を改修していただきまして、今回。","voiceIndex":63,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"この分室は、基本的には児童相談所ができるまでは、これを使っていくということでよろしいのでしょうか。","respondent":"崎村児童相談担当課長","answer":"ただ、現在、新庁舎の検討も行われておりますので、我々としては新庁舎の中に、こういった児童相談の部門というのがあったほうがいいのではないかということで要望は出しておりますので、そういったものを勘案しながら、こちらの物件をいつまで使うかというところについては。","voiceIndex":65,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"情報共有のところで、情報の管理は、個人情報の、非常に秘匿性の高いもので、この管理は大事だということはそのとおりで、今までもやってきたことについて、今回明文化したというところが大きいということでしたけれども、データというのは、基本的には電子データで保管しているということでよろしいのでしょうか。紙とか電子データとか、もしかしたら違う形があるのか、それをお伺いしたい。","respondent":"崎村児童相談担当課長","answer":"現在、警視庁の担当とやりとりをさせていただいている限りでは、メールですとかの電子での文書のやりとりではなく、口頭ベースでのやりとりで、それぞれの機関が記録をして保管するといったところでの共有を考えているところです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"そういった情報について、アクセスできる、触れられる人、知り得る人というのは、今、どういう形で管理されていますか。職員は全員触れられてしまうのですか。それとも、きちんとした管理のもと、担当者と上司のみとか、そういう情報へのアクセスの制限みたいなものというのは、どんな感じになっていますか。","respondent":"崎村児童相談担当課長","answer":"現在、我々が運用している児童家庭相談のシステムについては、児童相談担当の職員であれば、全員が閲覧することはできますけれども、ほかの職員は一切触れることはできないといったものです。","voiceIndex":70,"id":"exchange-027"},{"speaker":"塚本委員","kind":"意見","question":"今後、人も増えるということもありますし、一定程度、システムでアクセスをする形で最初から管理すると思うのですけれども、やはり今のご時世、いろいろなことでいろいろ漏れるということが、ある意味、非常に避けられないというか、リスクがどうしても高まってくる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-028"}]},{"id":"topic-03","title":"（仮称）品川区立児童相談所の開設時期","agenda":"（仮称）品川区立児童相談所の開設時期","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"児童相談所の開設時期を延期するということで、賢明な判断だと考えています。その中で、見直しの理由で、建物の設計について、可能な限り知見を集めて丁寧に設計をやっていくということですが、この間の検討の中で、問題になったところというのが何かあったのか、そこのところを具体的に伺えたらと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"人材の確保について、以前もお尋ねいただきましたが、人材は新たに採用する職員もおれば、庁内に異動する人間も一定程度おりますので、今の時点で具体的に何人という計画が決まったわけではありませんけれども、可能な限り優秀な人材を確保してまいりたいと考えております。","voiceIndex":77,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"設計のほうは、運営にも関わるというお話でした。人材のほうは、可能な限り集めていくということでしたけれども、児童相談所の開設が２年延びたことも含めて、ここまでに人材を確保し育成していくという計画とか見通しといったものを、ある程度もっていかないと、児童相談所の開設に向けて、しっかりと進めていくことができないのかなと思うのですが、その点はいかがでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"もう１点は、開設することが目的ではなくて、開設した後に、きちんと運営していかなければいけませんので、開設に必要な人間だけを集めてスタートさせます、というわけにはまいりませんので、その先も見据えて、しっかりと確保していかなければいけないというところで。","voiceIndex":79,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかったような、わからないような感じなのですが、令和６年度までということになりましたので、人材確保と育成に向けてしっかりと取り組んでいっていただきたいと思います。そういった中で、そういった検討も行っていくということで、民間委託の方針をもっているというのはやめるべきではないかと思うのですが、最後に伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"目的といたしましては、児童相談所の業務を効率的・効果的なものにするということを目的にしておりますので、まずはそれぞれの業務に求められる専門性とか、区の関わり方などの観点から、委託の可否を慎重に検討してまいりたいと考えております。委託ありきではございません。","voiceIndex":81,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"委託ありきではないというお話でした。実際に本当に民間委託しているところというのは、ほとんどないという状況です。それがどうしてかというと、しっかりとした対応を行っていくためには、やはり民間委託ではできないという判断だということだと思うのです。ぜひそういった面も考慮していただいて、しっかりと職員を採用できるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"何点かお伺いをします。今回、児童相談所の開設時期の見直しによって、今後の予定ですとか、建物の設計ですとか、そういったところに変更が出てくるということをご説明いただいたのですけれども、子ども家庭支援センターなど、ほかの部門でそれに伴う影響というのがありましたら、教えていただけたらと思います。私も、ぜひ丁寧に進めていただきたいという思いでおります。","respondent":"二ノ宮児童相談所移管担当課長","answer":"品川児童相談所との引き継ぎにつきましては、建物は近くの、大体信号１個分ぐらいの距離にはあるのですけれども、引き継ぎの仕方も、どういった形で引き継ぎをしていただけるのか、例えば、紙媒体で持ち歩くような話になれば、当然。","voiceIndex":85,"id":"exchange-033"},{"speaker":"横山委員","kind":"意見","question":"東京都との調整を含めて、また国の動きも、これからいろいろな状況によって変化もあるかもしれませんので、そういったところはアンテナを張っていただきながら、ぜひ慎重に、そして丁寧に、しっかりと進めていっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-034"}]},{"id":"topic-04","title":"三ツ木保育園の運営業務委託","agenda":"三ツ木保育園の運営業務委託","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、運営業務委託の事業者が選定されたということですが、今回応募されたのが７社あるということで、ほかの６社はどういったところだったのか、伺いたいと思います。そうすることで、ライクアカデミー株式会社がなぜ選ばれたのかということが、より透明性が増すということになると思うのですが、この点を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"選定にあたりまして点数をつけているかどうかというところなのですけれども、第１次評価、第２次評価につきましても、それぞれ事業者から提出された内容で、評価項目としましては、本事業の実施方針や区の理念と一致しているか、管理運営体制については。","voiceIndex":92,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"このライクアカデミー株式会社が一番点数が高かったところというのは、評価項目での一番よかったところといいますか、そこがどこだったのか、もう少し詳しく伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"第２次審査におきましても、当該事業者は説明がわかりやすかったものと認識しております。五反田に本社を置く区内事業者であり、一番最初の民営化保育園としては、区との連携がとりやすい事業者と考えているところです。","voiceIndex":94,"id":"exchange-036"}]},{"id":"topic-05","title":"ベビーシッター利用者支援の制度変更","agenda":"ベビーシッター利用者支援の制度変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、聞き逃したかもしれないのですが、そうすると、利用者の負担というのか、助成額というのか、そういったところが実際のところ、どう変わるのか、そこをもう一度確認させていただきたいと思います。今回、この変更をするに至った経緯を伺えればと思います。","respondent":"大澤保育支援課長","answer":"変更の理由ですが、都の補助制度を活用してございまして、都の補助制度の今までのバウチャー型と呼ばれる償還払いの制度が、令和２年４月から廃止になるということから、新制度への移行に至ったものです。","voiceIndex":100,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、利用者の負担は減るというご説明だったと思うのですが、ベビーシッターの利用料というのは、平均でいくと１時間当たり２,５００円ぐらいと考えてよいのですか。もし平均利用額等がわかれば、伺えればと思います。","respondent":"大澤保育支援課長","answer":"都の契約した事業者は、現在のところ１３事業者ありますので、それについては利用を希望される方には周知をしてまいります。","voiceIndex":102,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"これまで年間大体どれぐらいの人数の方、世帯というのですか、ご利用されているのか、実績を教えていただけますか。","respondent":"大澤保育支援課長","answer":"平成３０年度の利用実績が６名、令和元年度９月まで、前期の利用者数は２名です。","voiceIndex":105,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"一応、認可保育所等の申し込みが不承諾になった方が対象ということになっていますけれども、いわゆる一般の保育施設といったものを利用されずに、仕方なくという感じなのでしょうか。それとも、あえてという感じなのでしょうか。利用される方の状況、利用の理由はどんな感じになっているか、教えていただけますか。","respondent":"大澤保育支援課長","answer":"これまでのところ、不承諾の要件なく、あえてベビーシッターを利用したいというお声は、区には届いてございません。あくまでも自宅での保育になりますので、その部分がハードルが高いようで、なかなか利用実績としては、それほど伸びはないというのが現状です。","voiceIndex":107,"id":"exchange-040"}]},{"id":"topic-06","title":"認可保育園の新規開設等","agenda":"認可保育園の新規開設等","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"今回初めて品川区で実施する事業者というのはあるのかということの確認と、裏面の認定こども園の移行というのが、移行するに至った背景や経緯を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"１番の株式会社クオリスは、品川区にて開設するのは初めてですが、区外に複数、園を持っておりまして、隣りの大田区にも３園ありますので、地域的には一定のご理解はいただいているものと考えています。","voiceIndex":113,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"株式会社クオリスが初めてということで、職員の離職率ですとか勤続年数などといった点、働きやすさですとか、あとは事業の継続性とかを検討されていると思うのですが、そういった点を伺いたいと思います。認定こども園なのですが、移行されることによって、子どもですとか保護者への影響が、あるのかないのかも含めて、どういったことがあるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"人件費率が５２％ですので、離職率としては比較的低いほう、人件費率としては平均的な、一般的な保育事業者のものだと認識していますので、特にその中で職員の方が働きづらいようなことというのは、数値からは見えてきてございません。","voiceIndex":115,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"離職率とか人件費については、一般的な保育園の水準だというお話でした。人件費率５２％が一般的だというのが、むしろ衝撃的な気がするのですが。処遇改善にもつながってくるものだと思いますけれども、職場環境の点でも引き続き重視をしていただきたいと思います。認定こども園は、認定こども園に移行することによってのメリットといったところは、区としてはどのようにお考えでしょうか。","respondent":"大澤保育支援課長","answer":"認定こども園になりますと、地域子育ての支援事業をすることが義務づけられてきますので、在園児だけでなく、広く地域の親子向けに事業を展開していっていただくということで、区にとっても、区民にとってもメリットがあると考えております。","voiceIndex":117,"id":"exchange-043"}]},{"id":"topic-07","title":"上大崎三丁目教育・保育施設の事業者公募","agenda":"上大崎三丁目教育・保育施設の事業者公募","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"認定こども園で公募するということで、認定こども園ということにしたという理由を少し説明していただきたい。先ほどの保育施設で、はぐはぐキッズ中延が１年前に認可保育園で開設して、１年後に認定こども園化ということで、認定こども園ということに対する区の行政的な、ある種の思いがあるのかというところも気になったので、なぜ認定こども園にしたのかの説明をお願いします。","respondent":"大澤保育支援課長","answer":"あわせて、地域の子育てに貢献する事業が必須になってきますので、その辺りも重視をしております。","voiceIndex":123,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"今、そういう意味では、認可保育園の中で認定こども園化を考えているところというのは、結構あるのでしょうか。現状だけ、最後にお伺いします。","respondent":"大澤保育支援課長","answer":"今後、少し入園児が落ちついてきますと、保育の要件がない方も受け入れるという意味で、移行を検討する園も出てくるのではないかと考えます。","voiceIndex":125,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"応募の条件というのは、施設種別と付帯機能以外に何かあるのかということと、施設をつくっていくにあたって、住民の方からしっかりと声を聞いていただいて、説明会などを開いて周知もしていただくという進め方でお願いしたいと思うのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"地域住民の方のご意見ということですけれども、既に説明会等でいろいろなご意見が出ているところですので、今後、事業者が決まった後にも説明会を開いて、住民の意見を反映して設計等をすることを要件に入れたいと考えていますので、その辺りは事業者と協力して。","voiceIndex":128,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"認定こども園が重要で、そういった機能は不可欠だというお考えだと思うのですが、公立の認可保育園の認定こども園への移行については、どのようにお考えなのでしょうか。","respondent":"佐藤保育課長","answer":"品川区は幼保一体施設で認定こども園化するわけですけれども、そういう施設をたくさんもっている区もありますし、あまりもっていない区もあるというところで、なかなか足並みがそろっていないのが現時点での状況です。今後も引き続き検討してまいります。","voiceIndex":131,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、お話にあったような課題が解決しなければならず、なかなか難しい点だと思いますが、必要性というか重要性は認識されていると思いますので、ぜひ前向きに、他区などとも協議しながら、協力しながら進めていけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-048"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"どちらかというとマイスクールが教育重視で、フリースペースとかエールしながわは総合的なものなのかなというイメージをもっているのですけれども、その辺りの違いを教えてください。マイスクールに通われているお子さんが、子ども若者応援フリースペースやエールしながわを利用されているのか、重なって利用されている方はいらっしゃるのか、その辺りの状況をお聞かせください。","respondent":"大関教育総合支援センター長、廣田子ども育成課長","answer":"そこがフリースペースとは違う部分で、フリースペースの内容につきましては、この後、所管から説明があろうかと思いますが、併用という制度ではないのですけれども、実際にマイスクールに来ているお子さんでも。マイスクールに限らず、児童相談のほうであったりとか、必要があれば交流というか、情報共有であったりとか、一緒に支援をしていますので、どこでなければいけないというところではなく、かぶさるところもあるという形です。","voiceIndex":140,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"不登校やひきこもりというのは、本人や家族の責任にしてはいけないと思うのです。その中で、品川区が東京都や国に比べて出現率が低い、小学校・義務教育学校前期課程では０.５５％、中学校・義務教育学校後期課程では３.７１％ということになっておりますけれども、ほかのところよりも低くなっている原因など、理由の分析があれば伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"区として毎年行っている実態把握は、こちらの資料１枚目の表の右側にあった要因別・学年別内訳の表のとおりで、これは国と同じ項目で分析をしていますが、年齢とともに徐々にどう増えていっているのかなど、あるいは家庭に係る環境のさまざまな背景なども対応していきますと。","voiceIndex":144,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"学業不振によって不登校になっているというお子さんもいらっしゃるというところでは、一つの学校の問題点といいますか、教育をする場所ですから、そういったところで一つ、こういった問題が出てきているのかなと思いますので、落ちこぼれという言葉がいいかわかりませんけれども、そういう学業不振の方への支援というのも、しっかりと教育施設としてやっていっていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"したがいまして、マイスクール五反田などにおいては、先ほどご説明したｅライブラリなども活用しながら、本人が自分自身の必要な単元、教科書準拠の内容のドリルを学べる環境なども、マイスクール五反田やマイスクール浜川では、最近活用してきているところです。","voiceIndex":146,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"最初に聞けばよかったのですが、まず不登校やひきこもりという状態になった場合に、その人によって違うとは思うのですけれども、ここに相談すればいいという場所というのはどこになるのか、そこを伺いたいのと、マイスクールのほうは、今後の課題ということで、受入人数の拡大ということが書かれていますが、そうすると、マイスクールについては。","respondent":"大関教育総合支援センター長","answer":"今後、さらに子どもが増えてきますので、例えばマイスクール五反田やマイスクール浜川の午後の対応できるコースをもう少し工夫するなど、今、そういったことを考えて検討している最中です。","voiceIndex":148,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところも含め、当事者・家族に対して、区として適切な対応、そして支援の仕方、援助の仕方というのを、周知といいますか、お知らせをしていくということをしていかないと、ひきこもりの問題ですと、長期化という話が、今、社会問題になっておりますけれども、どういった対応をしていいのかということが家庭ですぐわからないというところで、長期化の問題が出てきているということもあると思うので。","respondent":"廣田子ども育成課長、大関教育総合支援センター長","answer":"藤里町でもお話を聞かれたかと思うのですけれども、支援しますという態度ではたどり着かないということなので、まずお話を聞いて、それぞれ１００人いれば１００様のことがあろうと思いますので、一つ一つ丁寧にやっていこうというのが。この３学期も、今月末ですけれども、今回は都立高校の先生方、管理職なども含めて、高校の進路に向けてのお話を中心に、親御さんからも質問を受けたり、座談会のような形で意見交換したりする予定です。","voiceIndex":150,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり人それぞれなので、きめ細かく対応していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"不登校のほう、資料２ページ目の成果で、９年生がそれぞれマイスクール八潮、五反田、浜川で２３人、高校進学の人数と全く同じになっていますが、これは９年生が全員、それぞれ３か所のマイスクールにいらっしゃっていた方が進学できたのだという捉え方でよろしいでしょうか。","respondent":"大関教育総合支援センター長","answer":"そのためにスタッフも、面接練習などもしっかりとやったりして、学校と連携しながら進めているところです。","voiceIndex":155,"id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"大変すばらしいと思います。それで、実際マイスクールに通っていない、通えていないというのか、不登校の人は品川区にはもっとたくさんいらっしゃるわけですけれども、自分も中学校の卒業式とかに出ていると、ほとんど“どこかに進路が決まっています”と毎年お話を聞いているのですけれども、大体進路というのは決まるものと捉えてよろしいのですか。","respondent":"大関教育総合支援センター長","answer":"たとえ不登校状態でも、進路の時期になりますと、どうしましょうと具体的に家庭と相談しながら、本人が希望される場合には、さまざまな進路をご紹介させていただいて、昨今は先ほど言いましたサポート校のような形などもありますので、何らかの進路を。","voiceIndex":157,"id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"そういう意味において、義務教育における必要な学力というものと、進路が決まっているという方についての学力の水準というのか、ほぼ高校に進学するのでしょうから、進学しているということは、一定程度の学力はもちろんあるのだろうと思うのですけれども、そういう部分は、学校には通えていなくてマイスクールとかだったけれども、進学できているということになるということでよろしいですか。","respondent":"大関教育総合支援センター長","answer":"あるいは、不登校でマイスクール八潮に通っていて、学校にほとんど行っていなかったお子さんでも、その後、大学に入ったとか、そういううれしい報告をしに来てくれた卒業生などもいますので、本人が将来の社会参加、自己実現に向けて何をしたいのか。","voiceIndex":159,"id":"exchange-057"},{"speaker":"塚本委員","kind":"質問","question":"民間にはいろいろなフリースクールみたいなものも最近見聞きしますけれども、いろいろだと思うので、そういうものを安易に勧めるわけにはいかない部分も現状としてはあると思いますが、今、３つのマイスクール八潮、五反田、浜川をやっていて、そういう多角的な生徒への対応というのが、今後の一つの流れなのかなと思いますけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"さまざまな選択肢の中で柔軟に進めつつも、区としては、やはりマイスクールのような核となる部分は、今後も充実させてまいりたいと考えています。","voiceIndex":161,"id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"ひきこもり支援についてなのですが、フリースペースのところで、課題としては出口というところで、なかなか一歩踏み出せないという話がありました。というか、小学生と３０歳を超えている人が一緒にいて、いづらくなるということが逆にあったりしないのかなと思ったりするのですけれども、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"５０代も、少しですが来ていたりとかするので、火曜日・木曜日に、別途１８歳以上を対象に、社会に出るための支援みたいなことで時間を設けました。フリースペースの時間帯については、来る時間帯がそれぞれ違っています。","voiceIndex":163,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"そういう部分では何もなくて、フリースペース等にとりあえず来ているというような方々についての出口というのは、サポートをしようとしても、なかなかないというところも実態としてはあるのかなと思って、そういう意味での出口をしっかりとつくって、一歩を踏み出させようというところにおける、利用している人へのある種の対応の違いというか。","respondent":"廣田子ども育成課長","answer":"何ならできるかというところを、自分たちで考えてというようにできればいいのですけれども、なかなか、お金のために、生きていくために働かねば、という感覚があまりなくて、我々もどう介入したらいいのかというところがあって、本人たちにとっては少しやってみると。","voiceIndex":165,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"そういう中で、もちろん１,５００人全員を相手にすれば、一番理想的なのでしょうけれども、そういうわけにもなかなかいかないでしょうから、出口ということも考えた上での事業というのを考えなければいけないという中では、どういう人が利用するのかというところの視点も、少し考えていくべきではないのかなと思っているところでありますので、そういった検討もしていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認で、そういったお子さんの所属というか、入って指導を受けることは、前提として認められているという認識でよろしいですか。そうすると、その先の高校に行ったり、ほかの進路に行ったりしたとしても、その後どうしているとか、元気だとかというフォローというのでしょうか、そういった体制はどのような形でとられているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"本来は特別支援教室のほうを、まずは活用していただき、不登校に至らないのが前提という形で、学校と教育委員会も対応しているところですけれども、結果的に不登校となってしまってマイスクールにというケースは、これまでもございました。現在もいます。","voiceIndex":169,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"意見","question":"発達のほうの話は承知しました。卒業後の話なのですが、資料に高校進学とありますけれども、次のステップに行っても、なかなかそこでうまくいかなかったりということも多いと思います。最後にその点を。","respondent":"大関教育総合支援センター長","answer":"教育総合支援センターとしては、１８歳までのお子さんに対する教育に関する相談窓口がありますので、そういったところを受け皿に、必要なところに支援をつなげるという形は今後もやってまいります。","voiceIndex":171,"id":"exchange-063"},{"speaker":"横山委員","kind":"質問","question":"２点、お伺いいたします。もし詳しくわかればというところなのですけれども、中学校を卒業して、その後というのは、現在どのようになっているのでしょうか。ひきこもりとかの要因として、大体高校くらいからということであると、都のリスタートの部門ですとか、教育相談室の１８歳までのところと、こちらのひきこもりの支援というところと、現在どのような形で連携をされているのでしょうか。","respondent":"大関教育総合支援センター長、廣田子ども育成課長","answer":"必ずしも進学だけではなくて、実際には高等学校はやめて働くという選択を、どういう形にせよ、ご自身の選ばれたお仕事をされているという方もたくさんいるのが実態ですので、卒業後のそれぞれの方のデータベースのような形は。卓球等やゲームだったりというところも、私もそれはどういうことかと思ったのですけれども、オンラインゲームだと相手があって、チャットの中で相談していたりとか、卓球は１人ではできないので、関わるということで。","voiceIndex":174,"id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"その子によって、好きなものとか趣味とか、一人ひとり違うと思うので、最終的には充実した人生を過ごしていけるように、どうしていくかというところに向けてのプログラムというか、いろいろな活動内容というのを、多分、今、試していただいているのだろうと思ったのですけれども、そういった考え方というか、やり方というのを、私はすごくすばらしいなと思いましたので。","respondent":"廣田子ども育成課長","answer":"我々が遊んでいるように見えるものでも、専門家やいろいろな方のご意見を聞きながら、導入していくというか、なおかつ自分たちで決めていくようにもっていくという形で、委員ご指摘のとおりで、取り組んでいきたいと考えています。","voiceIndex":177,"id":"exchange-065"},{"speaker":"横山委員","kind":"質問・要望","question":"状況を確認させていただきまして、ありがとうございました。その辺りは今後の課題として、さまざまな部門を超えて認識はしていただいているところかと思うのですけれども、今後、直接的な対応なのか、それともお子さんへのアプローチなのかとか、いろいろなやり方があると思いますので、ぜひ研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-066"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"横山委員","kind":"質問","question":"すみません、１点だけ。原因のところで、湿気による重みの可能性があるということをお聞きしたのですけれども、プールの近くにあるほかの更衣室ですとか、区内全体の施設については、どういった状況になっているのでしょうか。","respondent":"有馬庶務課長","answer":"今回は日野学園のプールということですけれども、ほかの温水プールについても至急調査をかけるということにしております。図面上で見ているのと、実際にどういうものかというところもあわせて、今、緊急の点検をしています。","voiceIndex":188,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":65272,"voices":190}},{"id":"r02-20200120-5","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"総務委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年陳情第６６号 情報公開請求に必要な研修の実施を求める陳情","agenda":"令和元年陳情第６６号 情報公開請求に必要な研修の実施を求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"具体的には大きく２点、文書件名を自分の考えで変更してしまったという対応と、１４日過ぎても決定通知が届かないことが何度もあったという陳情ですけれども、この対応について、適切だったと思うのか、不適切だったと思っているのか、伺いたいと思います。","respondent":"木村広報広聴課長","answer":"それから１４日以内ということで、過ぎても通知が届かないということでありますけれども、こちらも１４日以内に決定しておるところでございまして、その他こちらに書かれていることに関しましては、適切に区のほうで対応を進めてきたところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"という陳情の内容ですけれども、そういう対応をしなかった理由はなぜなのか、しかも当事者に問い合わせることもなく、情報公開請求の趣旨を解釈してしまう、変更してしまうというのは、ご本人にとっては、なぜだろうと思うのは当然のことだと思うのですけれども、なぜ部分公開決定とし、「設計図以外の図書は不存在」という対応をしなかったのか、するべきではなかったのかと思うのですけれども。","respondent":"木村広報広聴課長","answer":"１点目につきましては、実際に存在する文書が設計図しかなかった、この担当者のお答えどおりの状況でございまして、区は存在するもの全部を公開したです。１４日以内の件に関しましては、実際に郵送の遅延のようなことが事例としてございました。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"それも省略して、あるものが今回でいうと設計図のみだという決定をされてしまったら、やはり請求者にとってはなぜだろうと思います。そういう意味では各部署の窓口における対応については、改善が必要だと思います。窓口での対応や期間の取り扱いについて、年３回の研修の場で改めて強調といいますか、位置づけをするべきだと思うのですけれども、いかがでしょうか。","respondent":"木村広報広聴課長","answer":"ただいまのご指摘の点ですが、引き続き研修あるいは庁内周知等の場をもちまして、周知徹底に努めてまいりたいと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"今、情報公開請求の際に手渡されるといったご説明があったのですけれど、手渡される資料というのは、どこも統一ですかということと、この研修内容は、現在これで十分だと考えているのかという点と、この研修の対象者が、陳情の中では３点挙げられているのですけれど、これで正しいのかという部分をご説明ください。","respondent":"木村広報広聴課長","answer":"資料としてお渡ししているもの以外に、いわゆる口頭で、ポイントについてその資料に基づいて、ここはこうしてくださいというような形、それは具体的に申しますと、先ほどの１４日間の話ですとか、窓口でのやりとりですとか。","voiceIndex":14,"id":"exchange-004"},{"speaker":"田中委員","kind":"意見","question":"研修が十分かという部分で、実際に私たち生活者ネットワークも情報公開請求をよくするのですが、その際、今お話があったチラシの配布に関しては、正式に行ってくださったところは、私が今まで請求したところで１カ所しかありませんでした。なので、研修が十分だとはちょっと思えないのですが、そのことに関してお答えいただければと思います。","respondent":"木村広報広聴課長","answer":"それを各職場で展開して、やっていただいているところですが、今のようなお話も伺いましたので、引き続き各職場での周知、徹底を努めてまいりたいと考えています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"「設計図書一式」というのは、普通に使われている用語なのでしょうか。設計図というのはわかりますよね。そこのずれというのは、まずどういう資料があって、それをきちんと説明していないので、こういうことになるのですよね。情報公開請求が来たとき、どういう内容のものを公開することができるのか。そこをまとめていただくとか、それこそそういうのが情報共有だと思うのですが、いかがでしょうか。","respondent":"小林施設整備課長、木村広報広聴課長","answer":"「設計図書一式」というところでお答えします。字のごとく、設計図書、設計図がメーンです。設計図を書いていきますけれども、細かく第三者にその図面で読み取れないものも確かにあるのです。後段の、いわゆるそういうことがあった、それを共有するというお話です。大変貴重なご指摘です。実際に事例をもとにこういうところで話をする、いわゆる研修の中身として、考えてまいりたいと考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう取り決めになっているのでしょうか。「設計図書一式」と言ってくるということは、なぜこの言葉が出てきたのか。そうではなくて、情報共有とはどういうことが共有なのかということを、まず皆さんに知ってもらわないと、この施設は私が担当ではないというふうに思われてしまうと、そこでとまってしまうので、研修のあり方、説明の仕方というのは工夫していただきたいと思いますが、いかがですか。","respondent":"木村広報広聴課長","answer":"今のご指摘です。一つ、何かどこかのお話ということではなくてですが、実際にこういう事例があったということで、いわゆる個別にならないような形で、説明をしてまいりたいと考えています。","voiceIndex":22,"id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"要は、「設計図書一式」という言葉を使ってきたこと自体が、私はおかしいと思っているのです。ただ、「設計図書一式」と書いてあるので、そういう用語はなぜ出てくるのかと思うのです。それは相手側のことだからわからないと思うのですけれど、そういう言葉を使って表現している部分は今まであるのですか。それはいかがなのでしょうか。そこだけ確認したいと思います。","respondent":"木村広報広聴課長","answer":"調べますと、言葉そのものは「設計図書」という形でございまして、ただ定義といいますか、解釈がいろいろあるところです。委員おっしゃるように、この請求者の方がどういうことで、そういう形で書かれてきたか、なかなかあずかり知れないところです。","voiceIndex":26,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今後気をつけていただきたいのは、この請求をするときの言葉というのは、ずれることがあるのです。こちらの思っていることと、相手の請求していることがずれる可能性があるので、そこは必ず確認していただきたいと思います。この陳情の前半でおっしゃっていることは、そこの部分だと思いますので、ぜひ心がけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１４日云々ありますけれど、やはりいろいろな事情が出てくるではないですか。１４日でやりますよ、では中途半端な資料でいいのですかという話になると困るし、区としても出せない時期もあると思うので、そういうことでいろいろな対応があると思うのですが、その辺、情報公開請求が来たとき、区としては区民に、そういう丁寧な説明はされているのですよね。そこを教えてください。","respondent":"木村広報広聴課長","answer":"それから１４日以内の話ですが、先ほどの委員への説明と矛盾するところはあるかもしれませんけれど、各窓口ではご説明をして、対応しています。","voiceIndex":29,"id":"exchange-010"},{"speaker":"中塚委員","kind":"確認","question":"先ほど設計図書の説明の中で、設計図のほかに特記事項というものがあるというご説明がありましたけれども、今回の陳情者が請求をした事案については、その特記事項というのはないということなのか、そこを確認させてください。","respondent":"小林施設整備課長","answer":"先ほど、設計図書一式の中に図面、特記仕様関係があるというお話をしましたけれども、通常、図面と同等の大きさで特記仕様もその中に記入しますので、基本的には図面と一緒についてくるものですから、お渡ししていると考えております。","voiceIndex":32,"id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"公文書管理法に基づいて、自治体に対しても公文書の管理やファイルの仕方が、日常業務として位置づけられているかと思いますが、例えば区のホームページでもっと積極的に情報を提供して、誰もがいつでも情報を取得できる、そういう環境整備というものも、今後ますます必要になってくるかと思うのですけれども、その点についてもあわせて伺いたいと思います。","respondent":"小林施設整備課長、木村広報広聴課長","answer":"設計図書の中には特記仕様が含まれているのかというご質問ですけれども、含んでいると考えております。ホームページですけれども、かなり膨大な情報となるところもありますし、実際に表に出す、出さないという判断もありますので、その点につきましてはまだ研究課題とさせていただきたいと思いますけれども、まず窓口での聞き取り。","voiceIndex":34,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど表に出す、出さないも含めてとありましたけれど、基本的に表に出すものであって、出せないものを理由を付せればよいと思うのですけれど、そういったホームページ上の情報提供というのは、今後重大な課題だと思いますので、ぜひ検討を進めていただきたいと、関連して要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"情報公開の適切な取り扱いについては、先ほど来皆様のお話し合いの中で、課長もお話ししていました、しっかり聞き取りの徹底をして、またそれを周知していくということなので、ぜひそういった対応をしてわかりやすく、「設計図書一式」と「設計図」というところでも、認識を一致していくということは、請求するほうにも求められるのではないかというところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-014"},{"speaker":"小芝委員","kind":"意見","question":"本日結論を出すということで、今回の事例に関しては、ボタンのかけ違いといいますか、コミュニケーションの不足といいますか、そういったレベルでの話であるような印象を受けます。ですので、それを職員研修のレベルにまで引き上げていくというのは、はなはだ疑問が残ります。よって、この陳情に関しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういう意味ではきちっと、双方それぞれが伝わった、伝わるということを常に意識していくことを強化するような研修内容というのでしょうか、既存のものにそうした意識をもってしっかりやっていただくことが、こうした誤解なくやることだと思いますので、そうしたところを今後もしっかりと意識していただきながら、研修をしていただければと思いますので、本陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、態度については採択でお願いします。理由といたしましては、請求者に問い合わせることなく行ったという点と、実態として１４日を超えて決定通知書が届けられている、これはやはり不適切な対応だと思いますので、必要な研修をしっかり行うべきだと思います。あわせて、行政資料のホームページ上における積極的な情報提供を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は本日結論を出すということと、不採択でお願いしたいと思います。請求者は区民の方ですが、今までも対応されていると思いますが、なかなか理解していただけない方もいらっしゃると思うので、今後も丁寧な対応を心がけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。先ほど来、「設計図書一式」なのか、「設計図」なのかといったお話とかもあったのですけれども、これらについても本来ならば、きちんと窓口で請求者が何を求めているかという聞き取りが必要で、こういった表現だったら出すことはできますよという対応がされるべきだったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択です。請求するとき、住民の方はどういうものがあって、どういう言葉を使っていいか全然わからないと思うのです。なので、確認作業は必要かと思っています。「こういうものが必要なのでしょうか」という一言を担当の方が心がけていただければ、お互いに不要な行き違いがなく、済むのではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"}]},{"id":"topic-02","title":"品川区長期基本計画の策定状況","agenda":"品川区長期基本計画の策定状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区はこう考えている、区民はこう考えている、今後何か討論や意見を交わし合い、最終的な判断は当然必要ですけれども、特に今の区政と異なる意見に対してはより丁寧に、品川区は品川区の考えをお伝えしていく、区民は区民の思いを伝えていく、意見の違いがあってもそれぞれの考えが認識されるといいましょうか、そういう品川区、また行政であっていただきたいと思うのですけれども。","respondent":"柏原企画調整課長","answer":"運営といいますか運用の仕方ですね、今後の意見の聴取の仕方等も含めて、さまざまな方法は考えられますので、ただ、そうはいっても一定程度の予算の中で、期間も考えた中で動くというのもありますので、いただいたご意見を含めてどういった方向でできるかについても。","voiceIndex":52,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つだけ。賀詞交歓会でも品川区民憲章を毎年確認いたしますけれども、あれは「進んで区政に参加します」というふうに位置づけられているのですよね。ぜひ策定における住民の参加、また必要な情報の公開、説明会や区民同士、区と区民の意見交換、さまざまな場面をしっかりと位置づけていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"視覚障害のある方から、今、この長期基本計画が検討されていることも知らなかった、パブリックコメントもすることができなかったというお声をいただきました。次からの新しい長期基本計画は、ホームページ上で、きちんと視覚障害のある方たちに改定されたことのお知らせがされ、また読み取れるテキストになるのかというところを確認させていただきたいのですけれど、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"我々としましてもこちらの長期基本計画は、さまざまな方に知っていただくことが大切なことでありますので、その手法については検討しています。冊子についてもそういった方がきちんと理解できるように、ホームページのほうも工夫させていただきたいと思ってあります。","voiceIndex":55,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"この答申の生かし方なのですけれど、区長のほうに答申が上げられて、どういう活用の仕方を考えられているのか、そして区民への周知方法、通常であるならば何か小冊子か何かつくるのですかね。何かしらの形で伝えるのだろうと思うのですけれども、その二つをお伺いします。","respondent":"柏原企画調整課長","answer":"それで、それに基づいた施策を、予算等も絡むところですが、１０年間の計画の中で進めていくということになります。","voiceIndex":58,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"具体的に、各部署のほうに下ろされて、この長期基本計画に基づいた計画、それが実行という形に見えてくるのは、令和２年度の計画から反映されますよという形でよろしいでしょうか。品川区はこれから１０年間に対して何をしようとしているのか、というメッセージは、やはり区のほうから出向いていってすべき時期に来ているのではないかと思うのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"この長期基本計画のいただいた素案に関しましては、今、委員のご指摘もございましたけれども、さまざまな数値的なところについては今、検討しています。","voiceIndex":60,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"令和２年度の予算に反映していくということをおっしゃっていますが、そうすると私たちは、この長期基本計画に基づく予算というのが２月初めにプレス発表されて、予算書が出てきて、それを見て初めて知るという形になるのでしょうか。目標数値もきちんと出るのでしょうか。今度の令和２年度の予算審議のときに、この計画に基づいた事業という形で出てくるのでしょうか。","respondent":"柏原企画調整課長","answer":"それを今度は次の段階でいいますと、ブレークダウンするので、どういう形にするかはあれですけれど、実施計画的なものも検討しているところです。それをさらに単年度の予算という形でお示しして、動いていくというものです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、今の段階でそれが見えているかというと、全く見えないです。今からどうのこうの言うことはできませんけれども、せっかく素案という形で答申がまとめ上げられていて、３月には予算審議が入ってくるという中では、やはり長期基本計画をきっちり押さえた形で議論ができるように、情報も早目に出していただきたいと、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"},{"speaker":"つる副委員長","kind":"質問","question":"要するに令和２年度の予算として示されて、こういうふうにやっていきます、長期基本計画ではこう示されているから、その最初のスタートダッシュはこういう形で進んでいくのだという後に、３年間の総合実施計画というものが区民に示されていく、その辺のタイムラグを改めて教えてください。","respondent":"柏原企画調整課長","answer":"長期基本計画、この１０年間の考え方というのを、今回まとめていただきましたので、それに基づいて実施していきたいです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ただ、あとは示されるときも３年なら３年のスパンでこういうことで品川は進んでいくのだなというものを、ある程度理解した中での令和２年度の予算審議となると、より一層精度の高い審議、質疑ができるのかなというところでは、このタイミングだとなかなか難しいと思うのですが、さらなる１０年後にはどういうふうにその辺を示していくかということも、検討課題として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"長期基本計画をまとめていただいて、ありがとうあります。区の未来、将来をどういうふうに築き上げていくかという指針としてあると、区のこれから目指すものが、区民にもわかりやすくていいのかなと思います。何が起こるかわからない、この１０年なのかなという気がしましたので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-030"}]},{"id":"topic-03","title":"五反田公園他１４８箇所防犯カメラ設置工事請負契約","agenda":"五反田公園他１４８箇所防犯カメラ設置工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"「防犯カメラ作動中」という表示が、この図にもあるように防犯カメラのところについていて、普通に歩いていてわからない。なので、抑止力にならないのではないかと思いますし、そういう声もいただくのです。防犯カメラが作動していますよという周知がもっと届くような契約にならないのか、そういった契約がこの中に含まれているのか、確認させていただきたいというのが１点。","respondent":"立木経理課長","answer":"「防犯カメラ作動中」という表示に関しましても、そちらの仕様で触れられる内容かと考えていますので、私のほうからお答えすることは難しいと考えています。映っている範囲等に関しましては、それぞれの場所について最適な画角で設置を設計されていると考えています。","voiceIndex":73,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"防犯カメラ作動中といった周知のチラシとかは、契約の中に入っていないということなのかということと、カメラに映る範囲については、契約の中でここまで映りますといったことは示されないで、契約ということですか。","respondent":"立木経理課長","answer":"工事に当たって、例えば防犯カメラが作動しているかどうかというような、周囲の方への周知等に関しましては、恐らく工事説明の中でされるものかと思いますが、契約の中に例えばチラシを配ってくださいというようなところまでは、恐らく入ってなかろうかと考えています。","voiceIndex":75,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"このシールも、契約の中に含まれているのかということと、求めたいのは、現在のこの形だと、何かが起きたときの事後にこの防犯カメラは役に立つと思うのです。そういった、このシールなども、契約の中に示されているのかというところを知りたかったのですけれど。","respondent":"立木経理課長","answer":"防犯カメラが作動しているかどうかを周囲に知らしめて、それをもって防犯の向上ということに関しましては、所管のほうに伝えさせていただきたいと思います。","voiceIndex":77,"id":"exchange-033"},{"speaker":"小芝委員","kind":"確認","question":"確認ですけれども、今回の防犯カメラ設置工事をもって、区内全ての公園に防犯カメラが設置されるということでよろしいのでしょうか。","respondent":"立木経理課長","answer":"詳細につきましては私どもではわからないのですが、何年かかけて防犯カメラを設置していくということは聞いております。一部工事の調整等が必要な部分は、これから検討するということは聞いております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"小芝委員","kind":"質問・要望","question":"公園は犯罪の温床にもなりかねない場所でもあり、それは地域の方からも特殊詐欺事件とか、公然わいせつ事件の温床にもなると。特にそういったところも含めて、防犯カメラの設置を強化していただきたいと思いますし、公園によっては１カ所だけでなく、死角になるようなところも含めて、場合によっては増設されたほうがいいのかなと思います。意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"この書き方なのですけれど、五反田公園他１４８箇所と書いてありますけれど、なぜ「五反田公園他」と書くのかなと思って。実際は１４９箇所ですよね。防犯カメラは、あちこち設置している町会もたくさんあり、していない町会もあり、担当が違うとは思うのですけれども、補助金との関係の中で、設置をする決め手というのは何かあるのかどうか、いかがでしょうか。","respondent":"立木経理課長、品川財政課長","answer":"経理のほうには契約理由と起工書という形で回ってくるものでして、予算の後ろ盾みたいなところは、もちろん予算がないと起工もできませんし、契約類もできないのですけれども、その財源の部分に関しましては。補助のほうですけれども、東京都のほうで３分の１負担ということで、あとは区費になります。","voiceIndex":82,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"時期的なこととか、何か関係があるのですか。この時期とか関係なくいつでも、例えば区の事業としてまとまり次第、請求すれば補助金が下りるという感覚でよろしいでしょうか。","respondent":"品川財政課長","answer":"基本的に制度上３分の１ということで、あとは東京都の予算の範囲内ということにはなるかと思います。","voiceIndex":85,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"では年間を通して請求できるということで、よろしいですか。申請をするときの時期的なところがあるのかなと。それが部署によって、町会なら地域活動課とか、いろいろなところで出しているのですけれど、そのタイミングというのは何か決まりがなく、要求されたら自動的に、はい、どうぞと、予算の範囲内だったらいいですよというものか、それともこの時期にとか、そういう決まりはあるのでしょうか。","respondent":"品川財政課長","answer":"補助金は基本的には年度当初、申請をしまして、そこでおりる、おりないというところがあると思いますけれど、申請して、それによって年度末で予算の範囲で補助金が支給される、そういう形になります。","voiceIndex":87,"id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認なので教えていただきたいのですけれど、１４９カ所でカメラ設置工が２３５台ということは、公園によっては２台つくとか、そういう認識でいいのでしょうか。何か優先順位が、例えば安心・安全の防犯向上のためということでいうと、そういう要望が多いところからついていくのか、何か目安みたいな優先順位のような考え方があるのかなと思ったので、そこも教えていただければと思います。","respondent":"立木経理課長","answer":"１４９公園に対して台数が２３５台ということで、公園によりましては複数台設置されるというふうな内容になっているかと考えています。","voiceIndex":90,"id":"exchange-039"},{"speaker":"大倉委員","kind":"質問","question":"順番についてはわかりましたが、このとおり工事がされていくという認識でいいのですか。何か設置についての考え方というか、わかればと思ったのですけれど。","respondent":"立木経理課長","answer":"こちらは恐らく、区全体に散らばっているものでございまして、工事を施工する事業者のほうで、例えば近いところ同士をやっていくとか、そういった工程を所管課と打ち合わせした上で、施工されていくというふうに考えております。","voiceIndex":92,"id":"exchange-040"},{"speaker":"大倉委員","kind":"質問","question":"お話しいただいたとおり、効率のよい設置の形があるのかなと思うのと、一方、暗いところとか少し不安に思うところとか、住民の意見もあるのかなと思ったので伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"契約の報告なので、どう聞いたらいいのか考えていたのですけれど。工事を発注するということなので、映像の管理というのが同時にどう扱われるのかということも、やはり伺わなければいけないと思うのですけれど。工事を発注するに当たって、映像の管理は大事なことだと思うので、ご説明いただけたらと思います。","respondent":"立木経理課長","answer":"工事の発注に当たりましては、そこのところも考えられた上で経理課のほうに、契約依頼が来ているというふうに考えてあります。映像管理に関しましては所管のほうにもしっかりとするように、改めて伝えます。","voiceIndex":95,"id":"exchange-042"},{"speaker":"中塚委員","kind":"意見","question":"建設委員会での議論にはなりますが、やはり映像となりますので、個人情報であったり、プライバシーの問題であったり、また犯罪の抑制という視点もありますし、警察との映像提供の関係など、さまざまルール化は当然必要だと思いますので、一つよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-043"},{"speaker":"つる副委員長","kind":"質問","question":"今、中塚委員からもありました、基本的に所管の建設委員会のほうで細かい部分は、３カ年の最終年度ということですけれど。例えば今回の場合は公園の大きさによって、１台のところも２台のところもあるということなのか、その他の事由で２カ所、３カ所というところもあるのかとか、そういった意味で、経理課としてどこまで、こういうチェックというのでしょうか、やるのでしょうか。","respondent":"立木経理課長","answer":"基本的には、こういった事業をやるという形で、契約依頼が上がってきたものに関しましては、手続き上瑕疵がないものに関しましては、契約を順次をとらせていただくというようなスタンスで、やらせていただいております。","voiceIndex":98,"id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そうしたことも非常に大事かなと思いました。その犯人と思われる人を特定する、警察はそういう流れをしなければいけないのですけれど、その公園はたまたま設置がこれからだったという中で、近隣にカメラはないかということで、たまたま近くの一民間の方がつけられているカメラに、犯人と思われる方の映像があり、可能性が高いというところで確認の照会があったり。あくまでも、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-045"}]},{"id":"topic-04","title":"オリンピック・パラリンピック施設周辺道路遮熱性舗装工事（その２）請負契約","agenda":"オリンピック・パラリンピック施設周辺道路遮熱性舗装工事（その２）請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"オリンピックでマラソンコースになっているなら、それは十分よくわかるのですが、そんなに人通りがあるわけでなし、車の通りもそんなにあるわけでなし、区で率先してやるような話とは到底思えないのですが、これは都のほうから依頼があって、ここを遮熱性にしなければいけないということになって、都で補助金を１０分の１０出すからやってくださいという指示でやるのですか。予算のあり方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ。オリンピックでマラソンコースでもないのに、区でもいろいろなところで遮熱性塗装もやっていますが、なかなか区民の理解が得られるような場所ではないと私は思うので、いかがかなという意見だけは言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-047"}]},{"id":"topic-05","title":"地方税の賦課及び徴収事務における特定個人情報保護評価の実施結果","agenda":"地方税の賦課及び徴収事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"田中委員","kind":"意見","question":"パブリックコメントの実施結果についてです。０件ということで、総務委員会でも報告があったので、私も周知をしていなかったので申しわけなかったと思う部分もあるのですけれども、この０件というのはちょっとと思いまして、周知に関してどうだったのか聞きたいのですけれど。どのように周知されたのか、お知らせいただければと思います。","respondent":"伊東税務課長","answer":"今回、２回目という、再評価ということもあったのかなと思っているところでございまして、周知は前回同様、今の時期にやれる部分で一般的な周知という形でやったつもりではおるところですけれども、関心が少し薄かったのかなという気はしています。","voiceIndex":113,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"パブリックコメントはやはりとても、区民の方たちの意見が届く重要なものだと思うので、トップページのどこかにすぐ飛べるような、今このようなものをやっていますというものがいいのかどうかは、わからないですけれど、区民の方がすぐに気づくようなホームページのつくり方にしてほしいと思うのですけれど、その辺、いかがでしょうか。","respondent":"木村広報広聴課長","answer":"見やすく、わかりやすくということで、これはどうしても流れていってしまうのですけれど、募集を開始するときにはお知らせとして出させていただいて、そちらからも行けるのですけれども、どういう形がよろしいかどうか、これからも議論をしていきたいと考えております。","voiceIndex":115,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり関心をどう持っていただくのか、どうすれば意見を言いやすくなるのか、それを考えるのが、意見を求めている行政側の姿勢ではないのかなと思うのです。なので、今回の区民意見公募手続きにかかわらず、パブリックコメントをやる際には説明会を実施することを位置づけるべきだと、繰り返し求めてきました。","respondent":"伊東税務課長","answer":"国も、さまざまな形で周知をしているところでございまして、具体的なものに関しては、区のほうのそういう機会を捉えて見ていただきたいという話を、常々言っているところですので、これからまた、どういう周知方法が適切なのかというのは、その時点でもう一遍考えて。","voiceIndex":118,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"あくまで説明責任を果たすという姿勢で、行政はあるべきだし、それによって住民自治が成熟していくものだと、私は思いますので、ぜひパブリックコメントを実施する際には、改めて説明会を位置づけて、行政の説明責任を果たすという姿勢を強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"ではどこまで区民の方に、こういう情報をお知らせするか云々という話になると、さまざまな手法をやって、それで実際にどうだったのかということはありますけれど、本当に関心のある方はこれで対応して、それなりのコメントを区のほうに寄せてくれると思うので、今回のことに関しては、今後まだ続くわけですから、パブリックコメントは５年ごとにご意見を聞くということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33577,"voices":126}},{"id":"r02-20200121-14","meetingId":"r02-cm01","date":"2020年1月21日","dateIso":"2020-01-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区組織と関連団体に関すること","agenda":"区組織と関連団体に関すること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"国際友好協会とスポーツ協会それぞれについて伺いたいのですが、職員数のご説明がありましたが、これは給料が支給されている職員数が１１人、１８人ということでよろしいのでしょうか。確認をお願いします。そのうち、区の幹部職員のＯＢの方というのはそれぞれ何人いて、どの役職に就任されているのか伺います。そういったＯＢの方の待遇面について、区は把握をしているのかいないのか、伺います。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"職員数の１１人ですが、こちらは給与が払われている方が１１人です。それから、区の幹部職員ですが、事務局長に１名おります。はもともと区の係長級だった者がそれぞれ管理課長、事業課長などになっております。区との関係ですが、１８人中区の課長級の経験者が１名、事務局次長です。区の係長級経験者が６名、それぞれの係に入ってあります。区の一般職員の経験のある者が４名で、区と全く関係がない方が４名という形になってあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、国際友好協会のほうですが、区の助成金額が出ていますけれども、それが国際友好協会の事業費と運営費の合計と一致しているのですが、つまり、国際友好協会の活動費というのは、全て補助金で賄われているということになるのかと思うのですけれども、直営でやるのと違う点というのは一体どういう点が出てくるのかというのがわからなかったので、伺いたいと思います。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"こちら、資料のほうに記載されておりますのは、区からの助成金ということで、区から支出した金額になりまして、それぞれ財団のほうでも直営事業というものも幾つかございまして。それをもとにこちらも査定をする、それなりの対応をして、大体同程度のものを確保させていただいているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"品川区国際友好協会についてですが、多様な国際交流の推進と外国人に開かれた地域社会づくりを通じて、国際都市品川の発展に寄与して、世界平和の維持に貢献するという目的が書いてありますが、設立当時、昭和６１年と違って、多くの外国人が、観光だけでも３,０００万人以上の人が現に日本に訪れて、その中で国内でさまざまな国の方々と交流をしているという現状を見ると、このような、ポートランドとか。","respondent":"遠藤協働・国際担当課長","answer":"今後につきましても、これだけ長い間、今年度、ニュージーランドとジュネーヴのほうの青少年ホームステイがあったのですけれども、応募自体は十五、六人のところに６０人以上の方が申し込んでいるということで、一昨年なんかに比べますと。","voiceIndex":13,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今、青少年、中学生とか高校生が行かれていると思うのですが、この方たちのその後というのは、やはりアンケートとか何かは調べているのでしょうか。そうすると、そういうお金をそちらに回すならば、繰り返しますけれども、私はせっかく多くの方が日本に来ていただいているなら、そういう方たちと触れ合うチャンス、そちらに事業費を投入すべきだと思うのですが、その辺について再度お聞かせください。","respondent":"遠藤協働・国際担当課長","answer":"その後のボランティアみたいな活動というのは、確かに友好協会でもずっと課題だということでは認識しておりまして、来年から派遣した子たちをうまく組織化して、何らかの友好協会の事業なりを手伝っていただくとか、そのようなことができないかということで、今。","voiceIndex":15,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、お聞きして、意義としては、確かにこちらのほうもある意味で納得させられるところもあるのですが、ただ、国内のさまざまな自治体がやはり国際交流という予算枠、事業費というのを削減して、別の方向に向かっているということを考えますと、その辺、国際友好協会のほうも、私は何らか対応、見直し等を含めて、これから考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前回の文化振興事業団のときにも若干お伺いをしたのですけれども、いわゆる公益財団法人というところで、公益性が非常に強く求められるところ、当然、監査もあって、非常にクリアしなければいけないハードルというのが公益財団法人である以上は求められるのかというところなのですが、そうはいっても、このような事業費で、区との関係で多くの助成金を出しているという中で、区としての関与のあり方として。","respondent":"中元スポーツ推進課長、遠藤協働・国際担当課長","answer":"労務の社会保険労務士のモニタリングですが、体育館のほう、スポーツ協会のほうですが、区のほうで社会保険労務士による労務に関するチェックを定期的に実施する制度がございまして。実際に勤怠管理をきちんとやっているかというところは、友好協会の場合、第三庁舎の４階にありますので、私どももちょこちょこ行く機会がありますので、そんなところで、実際に私が見て、向こうの職員の方と話をして。","voiceIndex":18,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの須貝委員のお話とは逆なのですけれども、そういう意味で、区内での人材の活用というところをもう少し検討してみたらどうなのかというところで、ごめんなさい、前段階に戻ってしまいますけれども、例えば、職員体制は、民間ですから、どういう採用をするというのは、これはある意味、裁量に任されている部分もあるとは思うのですけれども、そういう職員の採用についても。","respondent":"遠藤協働・国際担当課長","answer":"そういう部分について、友好協会でもボランティアが大事だという認識がありますし、それを組織化をしたいというような話もありますので、その中でどういうことができるかというのを、区も一緒になって考えて、ボランティアの活用ができるような形を考えていきたいと思います。","voiceIndex":21,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"ホームステイで、はっきり言ってしまいますと、私の娘は昨年、スイスのジュネーヴに１７日間行かせていただきました。非常に得がたい体験をさせていただきました。スポーツ協会のほうで、ここで委託事業があるのですけれども、１０番にジュニアスポーツ教室運営および指導者養成委託というのがあるのですが、これはいわゆる再委託という形なのですかね。そこについて確認ができるのかどうか、教えてください。","respondent":"中元スポーツ推進課長","answer":"ジュニアスポーツとして今対象としておりますものの種目が連盟のほうにございましたら、連盟の方にご相談をして、指導者を派遣していただけるかどうかのご相談をしたり、連盟のほうで対応が難しければ、民間事業者の方、そういう専門事業者の方から見積もりをとって。","voiceIndex":23,"id":"exchange-008"},{"speaker":"芹澤委員","kind":"質問・要望","question":"国際交流のところでお伺いをいたします。先ほどから留学、ホームステイ等の話がありました。予算的な都合ももちろんあるのだと思うのですが、なかなか倍率が厳しいものがあるというのが一つあると思うのですが、この事業の予算を拡大していくという方向性はどうお考えなのでしょうか。もちろん受け入れ等の課題もあると思いますので、まずそれを１点お聞かせください。","respondent":"遠藤協働・国際担当課長","answer":"それにつきましても、まだ組織化できていない部分がありますので、その辺を含めて友好協会ときっちり話をして、検討していきたいと考えています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"基本的なところで、理事長はどのような過程を経て決められているのかというのを教えてください。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"理事長の決め方ですが、理事会の中で決めているです。スポーツ協会におきましても、理事会のほうにまずお名前の推薦がございまして、それを評議員会等で定款に基づいた手続をとりまして、承認していただいているところです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"その理事会というものの中で、国際友好協会、そして、スポーツ協会ですが、それぞれの分野において、知見ないし経験を持った方たちが理事になっていらっしゃるのかと思いますけれども、そこのところはどうなのか教えてください。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"国際友好協会のほうでは、例えば、地域になじんでいる方、あるいは学校の理事長だとか、あるいは会社の相談役の方だとか、そういう方が満遍なく、国際交流に一定程度通じている方中心に就任されているです。その加盟団体を大きく幾つかのグループに分けておりまして、その中からの推薦ということでお名前が理事会のほうにある程度上がってまいりまして、メンバーが決まってくるです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"経験をお持ちの方である以上、やはり両財団については、私は何がやりたいのだ、このような協会にしたいのだという意思をお持ちである方、そういう志のある方がかなりいらっしゃると思うのですけれども、そこの部分で、区のほうからある程度の助成金が入っているわけでして、理事長なり一定の協会の方向性を決める方たちに対して、独自性、独立性、あるいは組織の色を出す部分について。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"理事会の中におきましても、理事長を誰にするかというときに、理事会の中に私どもの副区長と教育長が入っておりますので、その辺で区のほうで一定程度、こういう方がふさわしいのではないかという形になろうかと思います。品川区スポーツ協会におきましても、理事会の中に副理事長、常務理事に区の幹部職員が入ってありますので、やはり人選についてでありますとか、また、方向性とか提案がございましたときには、区と十分に協議をした上で。","voiceIndex":33,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"独自性を保っていただくということ、これは重要なことであります。今、お二人の課長からのご答弁にもありましたが、区のほうから一定程度の意見を申しつけているという。話を聞く限りでは、私は、気を使っていらっしゃるというのはわかるのですけれども、独自性を担保するという形式上の意味からすると、非常にこれは不自然な形に思うのですけれども、どのように思われますでしょうか。","respondent":"中元スポーツ推進課長、遠藤協働・国際担当課長","answer":"スポーツ協会の場合でお話をしますと、もともと体育協会とレクリエーション協会という２つの団体であった時代から、区民の方々がつくっている連盟の方々が、地域で区民の方向けにスポーツ教室であったり。ただ、先ほど申しましたとおり、実際に理事とか評議員になる方につきましては、区のほうでもいろいろな形で相談を受けたり、あるいは実際にかかわったりというところで、一定程度担保はできているかと考えています。","voiceIndex":36,"id":"exchange-013"},{"speaker":"大沢委員","kind":"意見","question":"行政から指導、助成金をつぎ込んでということですので、一定程度は確かに必要だと思うのです。形式上というか、意識上、やはりあくまでも一定程度の独自性ではなくて、先ほど課長が言ったように、民間からもともとなったという話である以上、完全な意識でも形でも独自性が見えるような組織の形づくりというのが大事なのではないかと思うのですけれども、どのようにお思いになりますか。","respondent":"榎本総務部長","answer":"例えば、本当に独自性という意味でいくと、すごく大金持ちの理事の人が来て、寄付するから自分のやりたいようにやらせてくれと言われたときに、それをオーケーですと言うのか言わないのかという話になりますので。","voiceIndex":39,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"組織の現状を見る限り、部長がおっしゃることも十分にわかるのですが、ただ、説明を聞いていると、どうしても助成金の関係と組織の独立性といった場合、説明を聞く側にも問題意識と、発する側にもいろいろな考えがあるのでしょうけれども、そこのところでどうしても、一応、外の団体である以上、独自性、独立性が必要であるというのは思っているわけでありまして、そこのところの説明の仕方というか。","respondent":"榎本総務部長","answer":"今回の資料は、区との関連の部分が特に出ていますけれども、それぞれの団体は区議会の第２回定例会のときに事業計画と決算を全部出していますので、その中で全体像が見られるのかと考えています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"各連盟のほうがそれぞれ決算書をスポーツ協会にきちんと報告をしていると思うのですが、一部の方から、ある連盟に対して会計報告を見せていただけませんかという話をしたら、見せられませんという対応をされたということだったのですが、スポーツ協会としても、それぞれの連盟はきちんとした会計処理、事業報告をしているわけですから、そういうことに対して、実際これはあったことなのですが。","respondent":"中元スポーツ推進課長","answer":"現状は本当に十分認識をしていますが、何しろ区の中で場所がないというところもありますので、今後、もちろんそのような適地がございましたら、私どもの課としましても、そのようなスポーツができる施設をつくってほしいという予算要求のような形になりますでしょうか。","voiceIndex":44,"id":"exchange-016"}]},{"id":"topic-02","title":"旧国家公務員宿舎小山台住宅等解体工事の進捗状況","agenda":"旧国家公務員宿舎小山台住宅等解体工事の進捗状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"アスベストが出て延期することになったということなのですけれども、ご説明いただいたのですが、いま一つよくわからないので、重複になるかもしれないのですけれども、国のほうから説明を受けているのは、今ご説明いただいた限りなのでしょうか。どういう工事が必要になるのか。そこら辺は国から区は説明を受けているのではないかと思うのですが、そこら辺をお教え願いたい。","respondent":"柏原企画調整課長","answer":"国のほうから、モルタルも含めたアスベストに関しましては、これは今飛散しない状態になっておりますので、今の段階で何か特別危険があるということではないとは聞いてありますが、委員おっしゃったとおり、アスベストの解体に関しましては、かなりいろいろな対処といいますか。","voiceIndex":51,"id":"exchange-017"},{"speaker":"おくの委員","kind":"質問・要望","question":"区としてもまだまだわかっていないということですね。では、要望としましては、国から情報が入り次第、知らせていただきたいと思います。それから、この資料の５番目の東京都公園審議会の進捗状況というところなのですけれども、令和２年１月中旬から下旬に地域・利用団体との意見交換会と書いてありますが、地域というのはまだわかるにしても、利用団体というのは何のことなのでしょうか。","respondent":"柏原企画調整課長","answer":"公園を借りてというか、例えば、ボランティアの団体であったり、いろいろな方々がこちらのほうを、広いエリアですので、定期的に使ったりしている利用者といいますか、団体の方々がいらっしゃるということですので、東京都が把握しているということで、そういった方々に対して。","voiceIndex":53,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、国の発表、情報提供を待つしかないのですが、やはり近隣の方もかなり心配されると思うので、ある程度、こちらのほうでもわかる範囲で、また、国のほうにできるだけ早く聞いていただいて、どの程度安全性があるのか、危険性がどんな状況なのか、その辺をまとめて、近隣に話す時期もまた難しいかと思うのですが、その辺も対応していただきたいと思うのですが、どのような流れで行くのでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、住んでいた方々に何か影響があったかというところについては、国のほうの考えとしては、それはないという認識だろうです。近隣の方々への説明といいますか、今後の流れです。","voiceIndex":55,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"こういう建物に関して、こういうものでつくったという、おそらく図面、設計図書というのですか、そういうものが普通残っているわけですよね。それを解体するとか、そういうときに、国のほうでは、我々、各自治体をリードしているわけですから、そこがこんな状態ということは驚いたのですけれども、現状、全然国のほうでは認識がなかったということなのですね。少しお聞かせください。","respondent":"柏原企画調整課長","answer":"申しわけございません。そこの内部的な話につきましては、我々も把握できない部分ではありますけれども、ただ、あまり想定ができていない部分のアスベストだという話は聞いてあります。設計図書云々の話は、我々もわかりかねるところではあります。","voiceIndex":57,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"この検査自体なのですけれども、検査が始まった時期とか完了する時期についてというのは、区は聞いているのでしょうかというのがまず１点です。３点目は、先ほどおくの委員からありましたけれども、５番目のところの審議会で意見交換をやるというところは、東京都がということなのですけれども、地域と利用団体というのをもう少し具体的に、どういうところというのを、名前を教えていただければと思います。","respondent":"柏原企画調整課長","answer":"細かいスケジュールにつきましては、我々もまだ把握していないです。それから、都有地の取得につきましては、現段階の考え方といたしましては、来年度、令和２年度には取得したいということで、区としては考えているところです。","voiceIndex":59,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"検査のところについては、ぜひ把握していただきたいと思いますし、わかったらお知らせいただきたいと思います。それと、西側道路と東側道路が、当初想定から早期実施に向け調整中ということでお話がありましたけれども、これは令和３年、４年度からはそれぞれ延びるということでよろしいのか、伺います。これを先に行わなくてはいけない必要性というのはあるのか、そこら辺についてもお聞かせください。","respondent":"柏原企画調整課長","answer":"この辺もどのぐらい後ろといいますか、後に延びるのかというのは、今後の調整で、なるべく早い段階で整備したいという思いがありますので、おくれないような形で進めるという方向で、区は認識しています。","voiceIndex":61,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"最近、消防署の位置についても、近隣の発達障害のお子さんの保護者などからも心配の声も新たに伺ったりという状況もあります。共産党としても、本委員会で繰り返し求めてきたのですが、結局はそういうことは行われないまま来てしまいました。これは今回こういう予期せぬ事態が起こったわけですけれども、この時点でこれから修正していく意思があるのかというのも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"反対といいますか、意見が違っていらっしゃる方々もいらっしゃるというのは、これは事実でございまして、我々もそういった方々には丁寧な対応であったり、これから進む事業の説明を丁寧にお話をさせていただきたいということで。","voiceIndex":63,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"スケジュールなどの計画の変更点と、宿題になっていると私たちは考えていますけれども、今の現行の施設配置にした計画の根拠としている避難有効面積についての検証結果の公表など、今、こういう説明責任を果たす上でも、住民が求めているような情報も含めた説明会の開催というのを行うべきだと思いますし、それを求めたいのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"あと、東京都の公園審議会の関係で、今、いろいろな団体の方と意見交換を始めているようですので、これも主体となっている部分、その団体が責任を持って行うべきということでございまして、現段階で区が何らかの説明会ということになりますと、動いている事実というのが。","voiceIndex":65,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、こういう行為は、逆に長い目で見ると、こういう区が進めていくような計画も、さらに進捗させるどころか、逆行になるのではないかと思いますし、そういうやり方自体が間違っていると思いますので、ぜひ正して、やめていただきたいですし、説明会、これはスケジュール的なところもありますし、まだまだ尽くされていない説明がたくさんあるわけですから、これは主体は国だ、東京都だと言わずに。","respondent":"柏原企画調整課長","answer":"ご心配が上がっているというのもこちらのほうとしては認識していますし、その根拠たる部分についても説明をというお話があるのも、こちらについても認識があるところですので、そういったそれぞれのことに関しましては、区といたしましても、丁寧な説明。","voiceIndex":67,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29297,"voices":71}},{"id":"r02-20200122-18","meetingId":"r02-cm01","date":"2020年1月22日","dateIso":"2020-01-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"すみません、質問が違っていたらお許しください。大会のこのピッチの場所ではないのですけれども、隣に東京都の管理事務所がありますよね。要は、オリンピックの会場ができて、人がにぎわう中で、ああいうお食事どころがあるとすごくいいのかなと思っていたのですけれども、その予定はありませんみたいなことを施設の方から言われてしまったので、そこら辺を詳しく、もしわかっていたら、すみません。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"あそこのスポーツセンターの食事どころについては、大会終了後にどうするのかというのはまた考えるところなのかなというふうに思っています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本多委員","kind":"確認","question":"資料に書いてあるところで、ノースピッチは大会時１万席が２,６００席を残すということで、昨年の夏にプレでやった、このちょうどイラストで見る部分が２,６００席でしたか、その確認をしたいのと、あと大田区のほうのサウスピッチなのですが、大会時５,０００席で５００席を残すということなのですけれども、これは今まで既存であった客席ぐらいなのか、ちょっとその辺を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その周りにぐるりと仮設の座席をつくって１万席になるです。サウスピッチの５００席ですが、これは既存のできているところが５００席で、やはりこちらも同じように周りにぐるりと仮設の席ができまして、５,０００席になるです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"わかりました。すみません、大会が終わってからのこの公園の管理、今までは東京都だったのですけれども、その後も東京都のほうで管理されると思うのですが、何か品川区の役割が今までと変わるとか何か、例えば管理のお金がかかるランニングコストとか、そういったものも従来どおり東京都のほうで全額見ていくのか、管理とかコストについて教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの施設なのですが、公園全体として指定管理で受託している事業者でございまして、その事業者が引き続きやるように聞いております。特に品川区で費用負担するだとか、そういった話は聞いたことはありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"大会終了後もやはりこの大会を通じて区民、都民、国民のホッケーを中心とするスポーツ全体の意識が高まる取り組みも品川区として常に意識を持って取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"後利用についてなのですけれども、やはり東京オリンピック・パラリンピックに当たりまして、そうした文化プログラムというのも重要になってくるかと思いますし、今後の東京、品川の成長にとっては、文化交流という視点、そうした事業を伸ばしていくということが非常に重要かと考えておりますけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"おそらく音楽イベントという話になりますと、騒音の問題ですとか、いろいろクリアしなければいけない課題はあるかと思いますが、施設の一つとして考えられなくはないかなというふうに考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはりこの施設ができますと、この地域周辺にそうした大規模なイベントをできるような場所というのもなかったわけでありますし、せっかくこの機会、大井ホッケー競技場というオリンピック・パラリンピックに使われるすばらしい会場ができることになりますので、ぜひ積極的に文化イベントの活用、そしてそれに当たりまして、品川区からも積極的に提言をしていっていただきたいと考えていますけれども、その点。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういう意味では、指定管理の事業者とも品川区はわりと懇意にしているといいますか、いろいろ話す機会もありますので、そういった中では話の中でそういうことを伝えていくということは可能かなと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこの割り振りというのがこれから東京都に対して、区としてどういうふうに伝えていくのかというのが一つと、あと品川区と大田区がこの大井ふ頭中央海浜公園をまたがっているので、品川区も水辺の利活用、今いろいろな面でやっていただいていると思うのですけれども、そういうところで水辺の活用、あとバーベキューもできる、スポーツもできるというところで、品川区と大田区で何か連携して。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから水辺のイベント等では、たしか私の記憶では、ここではないのですけれども、水辺ということで、イベントを開催したことがあるのかなと思いますので、お隣の区ですし、連携できるときは連携して、うまく盛り上がっていくといいますか。","voiceIndex":16,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"まさにホッケーは品川区を挙げて小中学生もホッケー教室でやっているので、これは教育委員会との連携したこともやらなければいけないと思っているのですけれども、ぜひそういうホッケー競技として品川区の子どもたちにも、これから終わった後も、そこの拠点であるホッケー競技場で開催、何かしら競技大会にしてもそうですし、そういうスクールもやっていただきたいと思っているのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どももホッケー教室ということでずっと続けている中で、区内にもそういうチームが自主的にできているところですので、これはぜひホッケー協会等と連携しながら、引き続きこれを続けていきたいなと考えているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"基本的には大井ふ頭中央海浜公園は都立の公園なので、品川区からということは、先ほど筒井委員からあったように提言とか提案とか、そういった観点になってくるのかなと思います。ごめんなさい、委員長、確認なのですが、今日は大井ホッケー競技場だけ……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"わかりました。東京都のほうの資料、先ほど口頭でのご説明もありましたが、ホッケー競技場内、または公園内へにぎわいをもたらす施設となっていますけれども、競技場内となると、ピッチ内とか周辺部、大会時に７,４００席つくるその周りのことなのかなと思うのですけれども、考えられ得るにぎわいをもたらす施設というのは、どういうものが想定できるのか、わかれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういうところと連携できればいいのかなというように思っているのが一つと、なかなか誘致といいますと、専用のコート等を確保するとなると、やはりちょっと厳しい部分もあるのかなと考えていますが、何かそういうご縁がありましたら積極的に協力していきたいと考えています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"公園の中については都立の公園なので、東京都がどうこうということと、区としてもこういうのはどうでしょうかという提案があると思うのですが、例えば今後スポーツ施設というところではホッケーを中心としたさまざまなスポーツをされる方がプロ、アマ、両方の方が品川区内に住まわれるということを考えたときに、公園の周りにある程度少しゆっくりするとか、食事をするとか、何々するとか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周辺でなかなか土地的に言って難しい、採算性のこととかを考えると、土日はいっぱいいるけれども平日はいないとなると、なかなか採算がとれないということもあると思いますので、何か可能性を考えていきたいかなと思っています。","voiceIndex":28,"id":"exchange-011"},{"speaker":"西村委員","kind":"質問","question":"そもそもなのですが、大井ホッケー競技場というネーミングがこのまま続くのかどうか、いろいろなスポーツを行う中で、ホッケー競技場という競技場の中でいろいろなスポーツが行われるのかどうか教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場という名称なのですが、これは東京都の条例上この名前になっておりますので、このままでいくのかなというふうに認識しております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"西村委員","kind":"質問","question":"もう一つだけなのですけれども、先ほどのつる委員のご意見と少し重なる部分があるのですが、周りに何もないというところで、施設運営計画にもありますけれども、交流が生まれるにぎわい、地域的に広がりのあるレガシーをどこまで区として考えておられるか、立会川までは遠いですが、地域の方々をどう巻き込んでいくか、商店とか、何かそういったレガシー、お考えがあれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケー関係者の方でも、最近立会川あたりのお店に立ち寄って仲よくなったという話も聞いたりしておりますので、また一つ、商店街のにぎわいの一つにつながっていくのかなと思います。そのあたりは商店の方とお話をしながら今後進めていくのかなと思います。","voiceIndex":32,"id":"exchange-013"},{"speaker":"小芝委員","kind":"質問","question":"そういう意味で、立会川、勝島運河、そして京浜運河、そういった地域を巻き込んだ上でのホッケー競技場のレガシーを考えますと、もちろんスポーツ大会だとか、文化のイベントのときもそうですけれども、そうではないときも地域の人たちが気軽に立ち寄れるようなお散歩ルートといいますか、そういったところでホッケー競技場が一つのランドマークといいますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"公園の中に歩く距離が見られるような表示も出ておりますので、そういった形のお散歩ルートで、品川区の施設ではございませんが、広報紙等でご案内するだとか、そういった形で区民の皆様が親しめる施設にレガシーとしてなればいいかなと思っているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"資料について１点お伺いしたいのですが、先ほどからも少し説明がありましたけれども、後利用の方向性のところで、「総合的なスポーツ・レクリエーションの拠点」ということですとか、「共通事項・その他（諸室の活用）」ということで書かれておりますけれども、もう少し具体的な説明などがあれば伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういったいろいろなスポーツを楽しむといいますか、体験するイベントも考えられると思います。","voiceIndex":36,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"基本的には先ほど挙げられたサッカー、ラクロス、アメフトなどが中心として利用できていくということになるのですかね。どういった競技が利用できるのかというところで、ほかにあれば伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのほかの競技ということなのですが、具体的にはその３種目はよく挙がっているところなのですが、各スポーツ競技だけでなくても、例えば私どもが前にやったかけっこ教室ですとか、子ども向けの体を動かすようなものなどにも使われるかなというふうに思っております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"のだて委員","kind":"確認","question":"詳しくはわからないのですが、アメフトができるということだと、今子どもたちの間で、この間にワールドカップがあったので、ラグビーが注目を集めていると思うのですが、そこの確認をさせていただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、ゴールポストが立っていないということですとか、ショートパイルですと転んだときに痛かったり、熱を持ったりとかというのがあるので、どちらかというとラグビー、サッカーもそうなのですが、ロングパイルのほうが適切な感じがするので。","voiceIndex":42,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"パラアリーナの存続について、現在の状況を伺えればと思います。財団との交渉ですとか、そういったことをやられているのか伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"パラアリーナの存続の可能性というご質問です。パラアリーナは今までもご案内のとおり期間限定で建てられたということで、用途地域で博物館という決まりがございまして、なかなかその後は難しいというふうに依然として聞いております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"あわせて、今回東京でオリンピック・パラリンピック大会が行われるということで、品川区内において、スポーツ施設の整備というのをこの機会に進めていくことで、区内のスポーツ振興をさらに進めていくということにもつながると思うのですが、今回この大会を機に品川区においてスポーツ施設の整備をしていくお考えというのは、あと残り期間は少ないのですが、あるのかどうかというところも伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区内のスポーツ施設の整備についてですが、私どもではなくて、スポーツ推進課のほうでこれからスポーツ推進計画を立てていく予定になっておりますので、その中でどういうふうな施設整備のあり方がいいのかですとか、そういったことはもまれるかなと思いますので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"パラアリーナについては、引き続きぜひ要望を伝えていただきたいというふうに思います。こうした要望が実際に出ている箇所について、早急に整備を進めていただきたいというふうに思うのですが、わかる範囲で、これまでの取り組みですとか、今後の方向性、見通しを伺えればと思います。区内でのバリアフリーについて、どこまで進んでいるかというところも伺えればと思います。","respondent":"柏原企画調整課長","answer":"これは具体的な計画を今持っているというところではありませんけれども、今回長期基本計画をつくっていく中で、一つの大きな視点というところで捉えておりますので、実際に区の事業という中で進める部分と、それからあとどうしても区だけでは進められない部分。","voiceIndex":48,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところにかかわって、視覚障害の方ですとか、聴覚障害の方が観戦する際に、どういった支援があるのかというところで、何か実況というか、もっと詳しい解説を聞くような放送というか、ガイダンスみたいなものがあるのか、あるいは聴覚障害の方ですと手話とか、そういったことができるような場所があるのか、どういった観戦方法があるのかというところで伺いたいと思います。","respondent":"柏原企画調整課長、辻オリンピック・パラリンピック準備課長","answer":"ホームドアにつきましては、区のほうも早急に取り組むべきことということで、これは実際に取りつけるのは交通の事業者になってきますので、その働きかけということと、それから国や都の補助金等がありますので。東京都のほうで何かアプリ的なものをつくっているかに聞いておりますが、まだまだそれが障害を持っている方には、要するに伝わっていないところがあるのかもしれませんので。","voiceIndex":50,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"ホームドアのほうは、引き続きこの大会に向けて、最寄り駅ぐらいはぜひつけてほしいということで、事業者のほうにも強く働きかけをしていただきたいというふうに思います。最後にもしご答弁があれば伺えればと思います。","respondent":"柏原企画調整課長","answer":"ホームドアに関してですけれども、区といたしましても積極的に声がけといいますか、要請といいますか、させていただきたいと思いますが、大会期間までに間に合うかどうかというのは、設計があったりだとか、事業者の判断、お金のかかることですので。","voiceIndex":53,"id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"このホッケーの競技場が、大会が終わった後にイメージとしてホッケーの聖地になる、振興拠点ということで、大きなホッケーの全体として見た聖地になるのかなというイメージがあるのですけれども、品川区民がどのように気軽に使える場であるのかというところですね、そこのイメージをちょっと教えていただきたいと思います。そこら辺のところも教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"使い方としては、例えば団体で体を動かすことをやるとか、運動会をやろうなどというのは使えるのかなというふうに思いますが、個人でテニスのように二、三人で借りるという形ではないのかなというふうに認識しております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"そういう中で、こういう本当にすばらしい大きなホッケー競技場がありますので、何かしらこの品川区の中で、例えば個人にはなかなか支援はできないと思いますけれども、団体として何かやるというふうになったときには、品川区も共催をしていただくなり、協賛ですかね、そういう中での支援もぜひお考えをいただきたいと思いますが、いかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"現状の場合をまずご説明申し上げますと、陸上競技場、都立の今の公園のところにつきまして、品川区民スポーツ大会というもの、区が主催するマラソン大会をやる場合には、事前に優先で予約をさせていただけたりしているところがあります。","voiceIndex":57,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどからのご質問で、ちょっと思いついてしまったのですけれども、これは有形レガシーと無形レガシーの両方にかかわることなのですが、バリアフリーということで言うと、例えばスポーツ観戦や何かのところでのハード面のバリアフリーのお話が先ほど出てきましたが、東京都の施設なので、ぜひ東京都のほうに要望していただきたいのですが、バリアフリーのことについて品川区でもときどきというか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今後、後利用の際にもそういった当事者の方の意見というのは大切にしてほしいということは申し入れておきたいと思っています。","voiceIndex":59,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"条例とかがありますから、多分それはクリアされているのだと思うのですけれども、やはり私たちが見に行っても気づかない。だから、多分それは視点としてお持ちだと思いますけれども、一応品川区としてもその辺の確認していただきながら、今後も一緒に進めていっていただきたいと思います。それは要望ですので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-026"},{"speaker":"若林委員","kind":"確認","question":"先ほど、後利用の方向性が東京都のアドバイザリー会議の中での検討ということで、これが今後どういうふうに、どこでどのように、どんなスケジュールで最終的に固まっていくのかというのを確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回ご説明させていただいたのはアドバイザリー会議での提言に近いものでございまして、今後の使い方については私がつかんでいる状況ですと、担当の中で今もんでいるというところ、これをもとにどういうふうにしていくかというのは、何というのですかね。","voiceIndex":62,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問","question":"そうすると、半年、１年はゆうに、本当にこの地域がかちっと固まった形で、東京都という主体者、それから指定管理者という主体者がかちっと決まった形でオープンにしていくというのは、そのぐらいのスケジュールなのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それが、おそらく令和２年度いっぱいはかかるのではないかなというふうに認識しております。","voiceIndex":64,"id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"もう一つ、この大井ふ頭中央海浜公園の陸上競技場から野球場、テニス場とホッケー競技場、ホッケー競技場は今オリンピックであれですけれども、ここの全体の、公園を含む、含めなくていいのかな、競技場の区民の利用率というか、利用数というか、この地域をいわゆる品川区民が品川区の、別に品川区のということではないですけれども、認識をして、親しみを今持てているのか、また行きやすくなっているのか。","respondent":"中元スポーツ推進課長","answer":"都のルールに従った利用申請をされて、使われているというふうに、親しみはやはり距離的には近いですので持っていらっしゃるという感覚は課長としても持っております。","voiceIndex":66,"id":"exchange-029"},{"speaker":"若林委員","kind":"意見","question":"プラスアルファ公園といっても、荏原とか、ちょっといわゆる距離の遠い、それからまだ２６号線が開通していない、これから開通してもっと利便性が上がるという交通状況の中で、なかなか行かない。それをきっかけにと、そういうつくり方もあるのかなと思ったのですけれども、これは先ほどご答弁がありましたので、多分かぶると思うので、そんなことをちょっと考えましたということで意見に留めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そうした関係で、せっかく品川区とニュージーランドのオークランド市は友好都市でありますから、積極的にそうしたホッケーを通じての今後の交流、これは非常にいい機会かなと考えていますので、そうしたフレンドリーマッチとかを行って、国際交流とニュージーランドは強豪国ですから、国際標準の大会をぜひこの品川区の大井ホッケー競技場でやっていくと。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから国際大会というお話なのですが、この競技場は国際大会も一応できるような仕様になっておりますので、それは積極的に誘致しまして、区全体でおもてなしをするとか、そういった大会に来た人もまた品川区内で観光していただくとかいうことで。","voiceIndex":69,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"このニュージーランドのノースハーバースタジアムは、ラグビー場も備えているようなところでして、相当な規模ですので、単純にそのまま品川の大井ホッケー競技場で同じようなことができるかというのは難しいかと思いますけれども、そうしたニュージーランドのノースハーバースタジアムの使われ方というのもぜひ参考にしていっていただきたい、そして、それを東京都のほうにも連携をとって。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"規模が違うのでなかなか比較することは難しいと思うのですが、大井ふ頭中央海浜公園は品川区にある施設の中でもかなり大きくて、非常にいろいろなことが体験できるところと私は認識しております。","voiceIndex":71,"id":"exchange-032"}]},{"id":"topic-02","title":"東京２０２０オリンピック聖火リレーランナーおよびルートの決定","agenda":"東京２０２０オリンピック聖火リレーランナーおよびルートの決定","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"最近、地域の方、町会だとか、敬老会の方々と意見交換をすることが多いのですが、やはり地域の方の今年のオリンピック・パラリンピックに対する熱意というのをすごく感じてきまして、私も挨拶で聖火リレーの話をすると、いつ走るのかという話も聞かれます。そういう中で、確認をしたいのですけれども、セレブレーションの区の提供プログラムの中身を教えてもらってもよろしいですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ステージプログラムの区提供の部分ですが、ただいま検討中です。何か区を代表するようなといいますか、皆さんが楽しめるようなイベント、プログラムの内容で１５分を過ごしたいと考えています。","voiceIndex":78,"id":"exchange-033"},{"speaker":"小芝委員","kind":"質問・要望","question":"要望とします。一応ご意見をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのような形で、大会中にはいろいろな場所で皆さんの団体の成果、文化を披露する場面というのはありますので、私どもも伝わるようにご案内してまいりますが、ぜひアンテナを立てて手を挙げていただきたいと思っていますので、よろしくお願いします。","voiceIndex":80,"id":"exchange-034"},{"speaker":"筒井委員","kind":"確認","question":"聖火ランナーについて確認なのですけれども、品川区がこの方がいいのではないのかというご希望を出された方は結局決定したのですか。それで、いつのタイミングでお名前を公表されるのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今後どういうような形で、走る方がどこのどの区間を走るかとか、まだ決まっておりませんので、今のところは、私どもが要望した方が最終的に決まったかどうかということは、連絡がないところです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"つる委員","kind":"質問","question":"それから組織委員会が主催ですし、東京都との関係、そういったところが全て交通整理だとか誘導だとか安全対策をもろもろとっていく中で、当然品川区は協力要請というか、地元警察にもあると思うのですけれども、その辺の安全対策とかボランティアの、沿道でまずそもそも観戦していいのですかということですね。どこまでいいのか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"道路の広さはいろいろなのですが、ぜひ多くの方に見に来ていただいて、暑い時期なので、暑さ対策は各自お水を持ってきていただいて、応援をしていただけたらなと考えています。","voiceIndex":84,"id":"exchange-036"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった部分では、求められていないことの中でできる範囲の最大限というのでしょうか、やっていけないことは当然、余計なことはしなくていいと思うのですけれども、その中でも安全対策を一重、二重、三重にとってやっていく。１９６４年のときは１０月８日で時期も違うのですけれども、写真を見るとたぶん雨が降っていたのですかね。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"プレゼンティングパートナーを保護するといいますか、ブランド保護というのが非常に強いですので、ほぼできないのではないかなと思います。３キャラクターもルート上はちょっと難しいかなというふうに今のところ思っております。","voiceIndex":86,"id":"exchange-037"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう中で、許される範囲の中で品川区としてのアピールというのは最大限やってもらいたいなという思いがある一方で、やはり何かそうした周りで先ほどの安全対策ということもさることながら、そんなところでけちがつかないような万全な体制というのでしょうか、それもいろいろと組織委員会やそういったところと協議しながら、区としても未然に防ぐというのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それだけではなくて、地域の方も一緒にご協力いただきながら暑さ対策等も考えて盛り上げていきたいと考えています。","voiceIndex":88,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"今つる委員からご質問あったので、ちょっと関連するので一緒に伺いたいのですが、私はずっと道路の規制はどうなるのかなというのが気になっておりまして、例として箱根駅伝のことを出されましたが、そのレベルですむのかというのがあって、あれは規制があるのは片側だけですよね。もし何かあればお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"本当に東京都からいろいろなお願い事がなかなか来なくて、私どもも困っている部分はあるのですが、今おっしゃったように道路の規制ですね、今聞いているところでは、やはり先導車が来て、そろそろ来ますというので、その後にプレゼンティングパートナーのトラックが来たり。","voiceIndex":90,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"なるべく早くお願いしたいのですけれども、私のほうにそういうお問い合わせがあったときには、ではとりあえず品川区のオリンピック・パラリンピック準備課に問い合わせてくださいというような感じでよろしいのでしょうか。３月までに事業計画を立てなければいけないというのが、私もちょっと抜けていたなと思っていて、結構それは気にされている方が多いと思うのですが、そういうことでよろしいでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どものほうにご連絡いただきまして、お答えできるところはしますし、だめなところはまた調べたり等で何かレスポンスはします。","voiceIndex":92,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6568#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":31901,"voices":99}},{"id":"r02-20200123-10","meetingId":"r02-cm01","date":"2020年1月23日","dateIso":"2020-01-23","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"しかしながら、今、局長から、会派構成についてというお話がありましたけれども、私の意見というよりお願いなのでありますが、５月にさかのぼっていただいて、そのときの各派協議会でも決まりましたし、そこの時点で８・８ということでなっていましたので、確かに９名から８名に変わったということで、須貝議員からイレギュラーだというお話もありましたけれども、これは須貝議員のご意向のとおり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"今委員長が、本来であれば、第２会派である自民党の石田秀男委員長がやられていますけれども、そのままという形ですんなりと行くのが円滑ではないかと私どもは考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私ども自民党として、第２会派を務めさせていただいている中で、大沢副委員長からお話をいただきました。私どもとしては、受けるほうの立場なので、あまり言える部分でもないのですが、副委員長からのお話を踏まえて、流れとして、あくつ委員がおっしゃったとおり、５月のときにさかのぼって進めていただければと思いますので、その話を受けさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"同数であっても、今まで少なかったほうを第２会派とするということで今まで運営されてきたのが原則だと思いますので、お願いという話ではありますけれども、やはりどこの会派がというわけではなくて、その原則の考えは維持すべきではないかと思いますので、結論から言うと、今までの原則にのっとると、自・無が第１会派となり、自民が第２会派となるという原則がよろしいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"今、中塚委員のおっしゃったとおりだと思いますが、この時期に来て、議会運営ということを加味すれば、やはり同等数ということで、双方で話し合いで済むならば、私は双方の考え方を尊重したいと思います。今、１月に入っている、半ばを越えたので、ここでまたどうのこうの、いろいろ議運の変更云々があっても、それは困ると思うので、双方のご意見を尊重したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"大沢副委員長","kind":"意見","question":"賛成の方、そして、ご意見のある方、委員の方々にお話をいただきましたが、私、今回の場合は２回目のお願いでありますが、５月１４日の各派協議会をもとにここまで議会運営委員会、あるいは議会の運営をやってきたわけですので、今、須貝委員のお言葉にもありましたように、混乱という部分を鑑みれば、やはり私がお願いをして、現状のということと、もう一つ、石田秀男委員長と私。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"原則は変えるべきではないということで、今回の変更は、従来の原則を変えるものではないという点を確認したいのと、あと、当事者同士が話し合いがついているもとでお願いをされているというわけですから、それをことさら拒むというものでもないかとは思いますけれども、いわゆる従来の原則の考えは今後とも続けていくという点は、やはり改めて確認をしたいと思います。","respondent":"米田区議会事務局長","answer":"ただ、かつてそういう事象が発生したときには、会派順を入れかえずにということで、それまで多かった会派のほうが先の会派になるというのが前例としてあったということについては、この場で確認をさせていただければと思います。","voiceIndex":15,"id":"exchange-007"}]},{"id":"topic-02","title":"本会議最終日に付託する請願・陳情","agenda":"本会議最終日に付託する請願・陳情","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"これは今お話のあった提案に合わせてやっていっていいと思うのですが、当然、請願・陳情者に対してうまく説明をしていただいて、区民の不利益にならない形にしていただきたいというのが１点です。確認ですけれども、ほかの議会だと、どんな感じになっているか。そこら辺がもしわかれば、教えていただけますか。","respondent":"米田区議会事務局長","answer":"こちら、その区の事情に応じて定められているものだろうと考えています。","voiceIndex":44,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"今、鈴木真澄委員からお話があったこと、私も質問しようと思ったのですが、まず、請願権、陳情権というのは、おそらく我々が考えている以上に非常に重要なものであって、その日にちを１日前倒しにするということは、区民にとって不利益にもなりかねないということがあったのですが、ほかの議会と比べても、運用上の中でそういったことも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"いや、不利益になるのではないですか。１日減らすということは、それだけ出せる日がやはり減るということですから、その扱いについては、我々は慎重に考えなければいけないと思いますので、その点でも、現実の運用を考えて、他区と比較してもそれほどの極端な制限でもないということだと私は思いますので、私どもの会派としても、今回の変更は妥当ではないかという考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今回、このような案が出たというのは、妥当な案だと思います。やはりいきなり変わって、何だこれはという話になって、どこで決めたのですか、議運で決めたのですと言われても、それも我々からすれば心苦しいと思うので、その辺、この議運の中で柔軟な対応をするような、そういう期日を設けるのも私は大事なことではないかと思います。","respondent":"石田（秀）委員長、米田区議会事務局長","answer":"局長、もう一回特別委員会等への付託の話をして、できないとずっと宙ぶらりんになるということをもう一回説明してください。これは、良くしようとしているのだから。今の特別委員会等への付託のことをもう一回きちんと説明してください。そうしますと、今の現行の対応、それから、区民の方へ、お問い合わせがあれば、そういう形で前日までという形でお答えしていきますと、今のところはないのですが、仮に前日のぎりぎりにご提出があった場合。","voiceIndex":50,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"ただ、それは現実的ではないということで、それは重々承知をしておりますが、１日減るということは、それはやはり請願権、陳情権の制限になることには変わりありませんのでという意味で、先ほど申し上げました。ですから、おっしゃることはよくわかりますので、妥当だという結論に達したということを申し上げた次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"請願・陳情に対して、やはりシビアに考えられている区民の皆さんもいらっしゃるので、そこは十分なご理解を得て、また、きちんとした丁寧な説明をされるということで、どのような様子になるか、それは見てみないとわからないのですが、こういうことは例としてあったのですか。ぎりぎりで出されたということは。すみません、それだけ。","respondent":"米田区議会事務局長","answer":"現状といたしまして、議会運営委員会に間に合わずということはないですが、現状の規定ですと、そのおそれがあると。","voiceIndex":54,"id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"もちろん前日正午なのか、前日３時なのかは、いろいろご議論があってもいいと思うのですけれども、前日の目いっぱい夕方というのは、議会運営委員会の資料が前日に配付されるという部分と、あと、事務的というか、判断も含めた正副や事務局の時間も保障するという意味において、提出する方の権利をしっかりまた保障することは当然のことなのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"請願等については締め切り前でなくても、逆に言って、夕方５時過ぎぐらいにお見えになるケースも結構あるように見えるのですけれども、事務局はそこで対応しなければいけない。遅い時間に。事務局としてそのように対応してもらったらどうかと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"大きくは２つなのです。冒頭の本会議の規定は４日前ということで、それは変更する提案は全くなくて、最終本会議については、前日の正午または午後のいずれかの時間というのもよろしいのではないかと改めて説明をさせていただいたのですけれども、皆さんの合意の中で進んでいけたらと思います。相反する意見ではないので、全体の改正の方向は理解しているつもりなので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-016"},{"speaker":"須貝委員","kind":"意見","question":"私も、鈴木真澄委員がおっしゃったとおり、区民の立場として見た場合どうなのだということを考えると、夕刻、定時までは受け付けるという形のほうが、区民によりわかりやすいのではないかと思いますので、当面そういう形でやられたほうがいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会運営委員会の資料がさまざまある中で、本会議運営案の、あの資料の１枚がなかなか定まらないことで、全部の資料が前日各委員に配られるのがおくれてしまうという現象もあるのです。そういう意味では、このルールを確認した上でも、一回配った資料で請願・陳情の提出の追加があったので差しかえるという対応の仕方もできなくはないかと思ってはいるのです。要望を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"趣旨としては理解するのですけれども、やはり前日正午または午後のいずれかの時間の修正が合意できたらいいと。趣旨としては理解しているので、反対と言うつもりはないです。ただ、その修正をご理解いただけたらということで、態度表明をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"認知症サポーター養成講座ということで、区議会としてやろうというご提案で、よい取り組みだと思っているのですけれども、日程はいつぐらい……。","respondent":"渡辺議長","answer":"１定を閉じる前、前後も含めて予算特別委員会の総括が終わった後でどこか設定しようという感じです。今日はまずご了解を得られれば、方向性のご了解が得られれば、すぐ調整に入ろうと思います。日程は限られるとは思いますが。","voiceIndex":75,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":16999,"voices":85}},{"id":"r02-20200218-10","meetingId":"r02-cm02","date":"2020年2月18日","dateIso":"2020-02-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"および(2)の２件を一括して議題に供します。 本件","agenda":"および(2)の２件を一括して議題に供します。 本件","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"前に説明を受けたかもしれないのですが、３日目、２月２１日の質問者で、藤原議員、芹澤議員、くにば議員とあるのですが、本来今まで午前中に３人一緒にやるというふうに運用されていたと思うのですが、今回は何か理由があって午前中２人ということにされたのですか。","respondent":"米田区議会事務局長","answer":"本来そのような形で３人ということなのですが、全体な質問者数等と後の議事日程の流れを見て、このような形で組ませていただいているものです。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"東京都後期高齢者医療広域連合議会が、令和２年１月３０日１４時から開かれました。議員数３１名中３０名が出席、最初に一般質問が３名行われました。その後、給与、退職条例の専決の承認が２件ありました。それから、先ほど今度区議会としても第２５号議案でしたか、議案の中に後期高齢者医療の部分も出てきますので、その中でまたいろいろご審議、説明もあると思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"端的にこの間保険料の値上げには反対していただきたいと述べてきました。１点伺いたいのですけれども、一般質問ができるということですけれども、これは何か順番なのか希望なのか、私もそこまでよくわからないところはあるのですけれども、ぜひ保険料の引き下げに向けて、一般質問でも発言をしていただきたいと思っているのですが、その点だけお考えをお伺いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう保険料は決定しましたので、これから質問ということはできません。事前に質問通告をすることはできます。日程は決まっていますので、その中で通告をしまして、それで今回３名ということ。それから、各議案に対して討論もできますし、賛成討論、反対討論もできます。質疑もできます。最終的に私が質問しなかったのは、この現状やこれからの動きの中で賛成すべきと考えたからということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。いずれにしても区民生活が厳しくなっている中、保険料は引き下げるべきだと思いますので、改めて意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"１点だけ、議会費当初予算なのですけれども、職員給与費が金額としても大きく減っている点をもう少しご説明いただけたらと思います。思いとしては、やはり事務局はとても大事な存在だと私は思っておりますので、どういう状況なのかご説明いただけたらと思います。","respondent":"米田区議会事務局長","answer":"これは異動等もありますので、なかなか詳細につきましてはそこまでは見込めないということで、その１０月１日の現員現給の中で、前の年と比べて差が生じていることが一つあろうかなということと、それから、その中に手当等も含まれるものではありますが。","voiceIndex":32,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"議会費のところで、今回から防災備蓄を計上したということだったのですが、今まではどうだったのかというところ、いわゆる品川区役所のほうの備蓄が割り当てられていたのかというところと、今回具体的にどういうものを備蓄をされるのか。先ほど若干の例示がありましたけれども、もう少し詳しく教えていただければ。要するに我々の分も含むのか、職員の分も含むのか、その点も教えていただければと思います。","respondent":"米田区議会事務局長","answer":"これについて、従前ですと職員用ということで、防災課のほうで備蓄がありますので、今まではもしそういうようなことが起きれば、防災課のほうからもらってきてということになりますが、議会費として計上し、議員の分、それからそれを支援する事務局の分ということで。","voiceIndex":35,"id":"exchange-007"},{"speaker":"渡部委員","kind":"提案","question":"議会として、例えばそれぞれを保健所なり担当課に確認しても似通った内容であったりとかする中で、会派でまとめてというのでもよいのでしょうけれども、例えば今品川区議会は無所属議員も大勢いるような中で、例えば議会として、勝手なことを言うと、議長マターで情報集約、当然事務局のほうにも問い合わせるような形をとって、所管課から回答をもらうような仕組みにしないと。","respondent":"渡辺議長","answer":"今のご発言のとおり、いただいた意見も踏まえて、最新の状況と、例えば行政機関あるいは他区の状況とか、まず情報収集に努めてまいりたいと思います。そして、共通な取組の必要性が生じた場合、それぞれの会議体の責任者と相談するということを改めて進めていきたいと思います。","voiceIndex":39,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、渡部委員からもあったのですが、やはりこれだけ大変な問題になっているコロナウイルス、それから新型肺炎の件ですが、やはり我々区議会としても、区民の命、それから健康を守るために、区議会として品川区の区長のほうにきちんとした対応をしてくれという要望・要請をするべきだと私は思うのです。もし今日ご意見を聞かせていただければ、皆様もありがたいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"さらにここで議会の立場で一体何を要望するのか、何かやってくださいと要望するというのは非常に話としておかしな話で、具体的にでは何をどうしろというのが言えるならまだわかるのですけれども、対応してくださいというのは既にやっているのではないかなと、できる限りやっているというふうに私は判断しているんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"区議会として必要な対応をすることはもちろん大切なことだと思いますけれども、率直に言って日々刻々と変わっている中で、どう対応していいのかというところを見極めることが大事だと思うので、まずは先ほど議長からお話がありましたけれども、現状の情報共有、そこはしっかりとやる必要があると思うし、その上で必要な対応を、もちろん区民の健康。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-011"},{"speaker":"須貝委員","kind":"提案","question":"事情を把握して、そういういろいろな状況を見てという気持ちもわかりますが、やはりそれで初動がますますおくれて、区民の中で大きな問題となったら大変だと思うので、やはり区議会としてもさまざまな集会所や学校とかさまざまな施設がありますけれども、そういうところに対して早急な対応策を明示してくれということを言うべきではないかと私は思いまして、今、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"意見","question":"そうですね。しかし、もう既にこの段階でいろいろなご意見も出ている中で、なかなかこういう問題に対しての統一的な見解を素早く出さないとこれは意味のない話なのですが、なかなかそう早く出ないのではないかというところもあって、私の個人的な意見ですけれども、今のご意見に関しては、申し訳ないのですが委員長、議長にお任せしたいと思います。それしかちょっと言いようがないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12371,"voices":49}},{"id":"r02-20200221-3","meetingId":"r02-c-budget","date":"2020年2月21日","dateIso":"2020-02-21","committee":"予算特別委員会","time":"午後 ２時０５分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"新妻副委員長","kind":"意見","question":"ただいまご指名をいただきました公明党の新妻さえ子です。鈴木真澄委員長のもと、令和２年度のこの予算が滞りなく審議されますように取り組んでまいります。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1980,"voices":17}},{"id":"r02-20200221-10","meetingId":"r02-cm02","date":"2020年2月21日","dateIso":"2020-02-21","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今日の新聞報道や連日の報道で、結構議会のコロナウイルス対応、昨日北海道の町議さんか何かがやはり感染したということもあって、各議会が、開催も含めて、いろいろ延期やさまざま手を打っている中で、少なくとも議場に入る前や委員会室に入る前に手の消毒やそういうものを置くなど、そういったものというのは検討いただけないでしょうか。","respondent":"米田区議会事務局長","answer":"今お話のありましたもの、区の職員の対応の例に準じて、ご要請のありましたものについては、極力手配をさせていただきつつ、また必要な情報提供等については行わせていただければと思います。","voiceIndex":11,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1868,"voices":14}},{"id":"r02-20200225-6","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"区民委員会","time":"午前１０時００分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和２年陳情第１号 品川区立中小企業センター警備業務の改善に関する陳情","agenda":"令和２年陳情第１号 品川区立中小企業センター警備業務の改善に関する陳情","exchanges":[{"speaker":"くにば委員","kind":"提案","question":"それぞれの個々の施設であるとか、もちろん区が所管している施設に関してもあると思うのですけれども、個別の施設に対して改善提案をしたり、あとは苦情のほうを申し上げていただいたりする形でご対応いただければというのが私の感想ではあるのですが、警備業務の契約不履行という部分のワードについてなのですけれども、これについては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"貸し出しが終わって、そうすると受付に鍵などを返して、そのような方々が多少おしゃべりなどをしながら出ていく、そういったところも考えると、２１時４０分や４５分ぐらいになる可能性があるかなと思うのですけれども、それで業務は２２時に終了、そうすると、その間２０分から１５分、そのぐらいが誰もいない時間かなと思うのですが、その全体巡回に関してはどのぐらいの時間を要するのかというところで。","respondent":"山崎商業・ものづくり課長","answer":"通常、警備業務が７時に始まるということであれば、要は入館する時間帯というのは７時には警備員服にお着替えをされて、準備してというようなこと、これは通常の私どもの業務も一緒で、人によっては５分前に来てすっと間に合う方もいれば。","voiceIndex":7,"id":"exchange-002"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ委託業者との信頼関係というものが非常に大事だと思いますので、その中で、この全体巡回、それに関してはやはり夜の２２時から翌７時までは、基本的には誰もいない時間となりますので、しっかりと施錠されているか、そういったところは委託するときの内容などにも、もしあれでしたら取り込んでいただいて、今後も事故がないようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"いろいろお話もお聞きしました。それを聞いてすごく、その１人の方の時間帯がすごく長いかなと単純に感じたのですけれども、そういったものというのは、働き方の規則の中ではどういったものなのかと教えてもらいたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"朝から夜までの時間帯で、どうしても限られた人数で効率的に回していくですので、通しの方も途中で、当然労働基準法に定める範囲の休憩、休息のほうは入れさせていただいているというふうに警備会社のほうからは伺っております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、私もこの陳情者の方がこのようにいい意味で業務のことをお話というか、文書に出してくれてありがたいと思っている１人なのですが、この方は平成３１年３月３１日までいらっしゃったわけですね。は。それでわからないのは、平成３１年４月１日からは警備会社が変わったのですね。変わった。そこを確認したいです。","respondent":"山崎商業・ものづくり課長","answer":"警備業務の区としての委託先につきましては、令和元年度、今年度から新しい警備会社に切り替わっております。それから平成３０年度、昨年度につきましては、警備員７名体制のうち１名のみ替わられて、６名が新会社で雇用を継続されているというような状況です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"ということは、陳情の理由に出ていますが、この陳情者の方は平成３１年３月３１日までにこのようなことがあったのですということを言っていらっしゃるのか、そうではなくて、おやめになった後も中小企業センター等へ行かれて、いろいろ業務がこうだとか、遅刻があるというようなことを言っているのか、これいつの時期のことを言っているんですか。それともずっと連続しているのですか。","respondent":"山崎商業・ものづくり課長","answer":"質問項目によって違いますけれども、例えば、当時警備員として勤務をしていただいた時代の警備の体制のことや、あるいは警備員さん同士のこと、言ってみればそのような時間軸の話と、あとそれからそのときに、例えば先ほど改善されたところで、消灯して帰っていたのだけれども。","voiceIndex":15,"id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"だけれども、もしあったときに、だってわからないではないですか。ご審議いただこうと考え、陳情を提出しましたというものが、今日出てきているわけですけれども、やはりこの辺だけの確認というのが、すぐ、もうしていると思うのですが、きちんとしていただかないと、私は一番この2)、るるあると思うけれども、ここが大事だと感じているのですが、その辺については事実関係を含め、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そのときはどうなのですかという話の中では、それは個々に備えて３０分前だとか、５分前だとかというような、そのようなことについては、通常の私どもの業務と同様ですというようなことでお話をさせていただいたです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"藤原委員","kind":"確認","question":"では確認します。大事なので。2)ですけれども、区としては、現場責任者が朝の遅刻常習者なのに放置されてきたという文章が出ていますけれども、これは放置されていないということですね。","respondent":"山崎商業・ものづくり課長","answer":"そうした事実はなしということで確認をしています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"１点、今の答弁等からバックしてしまうのですけれども、戻ってしまいますが、そもそも平成３１年３月３１日に、もとの警備会社から違う会社に変えた理由は教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"ただ、これは区の委託内容に変更がなく、かつ受託者の履行状況が良好であれば、３年間を限度として、同一受託者と契約することが可としますということになっています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"基本的な確認をまずします。ほかの委員ともちょっと重なるところもあるかもしれないのですが、そもそもこの陳情者の方が勤めていたときに、1)番に書かれているような業務改善を求めるいろいろな案というものは、直接雇用してくださっているその会社に、きちんとこのような改善、あのような改善というものはされていたのでしょうか。そこを確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの７名の警備員の方々のチームがありまして、そこに実際の現場を仕切る現場長の方がいて、そうした警備員さん同士でありますとか、現場のリーダーの方とのコミュニケーションというものは、通常の警備業務を効率的に行う意味でも。","voiceIndex":23,"id":"exchange-010"},{"speaker":"こんの副委員長","kind":"意見","question":"そのような中でも声が上がって、仕様書の上で改善できる点は改善してきたと思われるのですが、それでも改善がされないという思いで出されてきたということなのですけれども、2)番の遅刻者についても、本来ならば雇用している会社がきちんとその人に指導していくという、区が直接その人を雇用しているわけではないので、指導していくということが通常だと思われるのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"理由につきましては、警備について業務委託をしていますし、また、陳情者がおっしゃっている警備会社が既に変わっていて、理事者からも陳情内容については改善が図られたという説明があったので、不採択でお願いしたいと思います。ただし、今後も区民からのこういった指摘に関しては、十分に耳を傾けていただいて、警備会社と適切な業務委託をして、さらなる防犯に努めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"松澤委員","kind":"意見","question":"事件も起こっていない、それで令和元年３月３１日以降も継続して皆さんしっかりとやられているというお話が出ていますので、問題はないのではないかと思います。副委員長よりお話がありましたけれども、いろいろこういった問題というものはこれから多くなると思いますが、やはり区と区民の信頼という形で、しっかり窓口対応していただけたらと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-013"},{"speaker":"こんの副委員長","kind":"意見","question":"結論を出すでお願いします。結論としては不採択ということでお願いしたいと思います。先ほども申し上げましたとおり、区としても対応し、また、業務改善をきちんと対応されてきた、そのあかしとして、特段の重大な事件が、幸いにも起こっていないということもありましたので、今後もこうした改善をできる限り進めていただきながら、これからも防犯、安全に万全を期していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-014"},{"speaker":"おくの委員","kind":"意見","question":"結論を出すで、趣旨採択でお願いします。ここに書いてある陳情の要旨というところで、改善を図ることや、誠実に対応しというところの趣旨が非常に理解できるというところが、この中の趣旨で私は明らかになったと思います。ただ、事実関係など、まだまだわからない点なり、細かいところまでは縛れない点なり、十分に行き届かない点があると思うので、趣旨採択ということでいきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。不採択ということですけれども、区民お一人お一人の意見という意味では、行政としては受けとめるという姿勢は真摯に受けとめていただいて、区民の安心・安全のためにこれからも尽力していただきたいと願っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"実際にそれで私が業務をかつて行っていた中で、特に問題がない範囲できちんと業務を行っていたというのは、例えば本当に課長がおっしゃっていたような形で、実際に３０分前に来ましょうというような契約というか、会社の中での話し合いがあって、ただそのおっしゃっていた形で、特にこの方はベテラン、現場責任者の方ですから、どういった形でやれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-017"}]},{"id":"topic-02","title":"令和２年陳情第１４号 こみぷら八潮にシャワーブースと入浴施設の整備を求める陳情","agenda":"令和２年陳情第１４号 こみぷら八潮にシャワーブースと入浴施設の整備を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"だから、少しずつ設けていっておかしくはないのではないでしょうか。ですから、やはり公衆浴場が１つぐらいはあって、余り寒くないお昼の時間帯に行けて、そこでコミュニケーションも図れるというような場を公共の力で、それほど費用のかかる話でもないと思いますから、つくるということは、この陳情をきっかけに真面目に考えてあげてもいいのではないかと私は非常に素朴に思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-018"},{"speaker":"湯澤委員","kind":"質問・要望","question":"もし分かればで結構です。それからあと最後に、八潮南小学校の体育館での避難生活で苦労があったというように書いてあるのですけれども、苦労というのは当時どのような対応をされていて、どのような苦労があったのかということがわかれば、教えていただきたいと思います。","respondent":"古巻文化観光課長","answer":"３つほど質問いただいていますけれども、お答えができるものとできないものがありますが、浴室のない住宅、まず八潮地区ですけれども、基本的にはないというふうに認識をしております。皆さん方、ご自宅に浴室があるという住宅にお住まいになっているという認識です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"湯澤委員","kind":"意見","question":"おくの委員おっしゃるように銭湯に入りたいという、私もよく行くところはあるのですけれども、ただ、浴場組合の皆様などはどんどん入る人が少なくなってきて、廃業するという方が私の周りにも何人もいらっしゃって、そういったところで、やはり営業していくには相当なお金もかかりますし、それからまた八潮へそういったところを、公衆浴場をつくるというようになっていくと、ほかの公衆浴場の皆さんも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問・要望","question":"入浴施設なのですが、私もお風呂が大好きで、予特でも質問させていただきましたけれども、やはり大切な、これは要望というのですか、思いというのですか、銭湯をつくってくれというか、やはり私もすごく、とても大切な、高齢者が自宅で亡くなる心配もない、いろいろな方が集まるというところでは、私も入浴施設はつくってほしいかなとは思っていますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-021"},{"speaker":"おくの委員","kind":"意見","question":"私自身はうちにお風呂がありますけれども、共産党の事務所に宿直を週１回やっていますもので、そのときだけは銭湯に行っているのです。今日もそうなのですけれども。コミュニティの場をこみゅにてぃぷらざ八潮につくるというので本当にふさわしい、１つのスポーツ施設とか、会議室とか、それだけではなく、施設のもう一つの新しい形態だという形でつくれるのではないかと私は思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-022"},{"speaker":"こんの副委員長","kind":"確認","question":"改めて、まず確認なのですが、先ほどもご説明いただきましたけれども、他の学校施設と同様にという位置づけなのだというお話なのですが、改めて各学校の体育館、いろいろな方々がスポーツを楽しまれている学校にはシャワーがついておりましたでしょうかというところをまず確認、ついていないということはわかっておりますけれども、いわゆるスポーツを楽しむ施設の１つとして、こみぷらも。","respondent":"古巻文化観光課長","answer":"ゆうゆうプラザになれば、また浴室については同じように利用できるような形にはなろうかと思いますので、そういった形ではご利用いただけているケースもあるかなと考えています。","voiceIndex":49,"id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"現状、まず確認をさせていただきました。その点で、いわゆる八潮のこみぷらも、それから先ほど申し上げた文化センターも、１つのお部屋がスポーツ施設になっている、こうした施設へのそのような入浴施設の考え方というものは、現時点でどのようにお考えなのか、その辺をちょっと確認させていただきたいと思います。","respondent":"古巻文化観光課長","answer":"その利用とニーズ等を踏まえて適切に施設を整備し、うまく運用しているというようなところですので、現時点で文化センターであったりといった、スポーツを主として使われていない施設、ほかの目的が、どちらがメーンかというのは難しい問題がありますけれども。","voiceIndex":51,"id":"exchange-024"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"高齢者というように書かれていますけれども、高齢者のこの入浴に関しては、やはりこのこみぷらのそもそもの目的からすると、高齢者の安全対策のためとは少し目的が違ってしまうと思いますので、その辺のところは、たしかここの八潮は地区計画のような形で、地域の方々がまちづくりとして、非常に会長含めていろいろと考えていらっしゃる地域だと思うので、その中でもいろいろな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"なので、やはり八潮の中に１カ所はどうしても、こみゅにてぃぷらざ八潮というのは八潮の中でも大事な施設ですから、ここの中に１つシャワーであるとか、入浴の設備というものがあっていいのかなと思います。自宅以外に避難をする、広域避難所として入浴施設があってもいいのかなと思います。そちら２点、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"施設そのものをつくることが、先ほど住宅の基準の中でどうなのかわからないという部分もあったのですけれども、例えば海の家にあるようなというか、いたって簡易なシャワーのみの施設というものをつくるのは、果たしてそんなに難しいのかどうかということは私はわからない部分なのですが、そのような最低限、最低限というか、全体として、そのような細かい部分というものをより歩み寄りではないのですが。","respondent":"古巻文化観光課長","answer":"ですから、文化観光課という１所管がどうこうというところは、もちろん文化観光課からの提案というものはあり得る話ではありますけれども、ただ、現状では文化観光課からというようなことは考えておりませんし、またそういう意味でいうと。","voiceIndex":57,"id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。理事者からのご説明をもとに議論をしたとおり、本件は不採択という考えになりました。ただ、高齢者等の入浴の安全を保つために、先ほど課長からご説明もありましたように、浴室の整備に対して八潮地区だけにかかわらず、しっかりとしたバランスで対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"結論を出すでお願いします。不採択でお願いいたします。いろいろ皆さんから質問、また理事者のお話を聞いたとおりで、いろいろこの文章の中でも、そもそもないからつくってくれというのは難しいお話であるかなと考えますし、八潮団地もいろいろな、シャワーやお風呂が各家庭についているという部分で、ここに早急にシャワーブースが必要かと考えると、これはまだ要らない話ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-029"},{"speaker":"おくの委員","kind":"質問","question":"結論を出すで、採択でお願いします。理由としては、やはり先ほど述べたとおりといえばそういうことですけれども、バランス論なども出ていますが、むしろこれを機にほかの施設もつけるような方向で、シャワーブースなどもつけるような方向で、もう一度見直すぐらいの観点で考えていったほうがいいのではないかというようなことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"結論を出すで、不採択で、理由はこの委員会の質問、答弁の結果です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-031"},{"speaker":"くにば委員","kind":"意見","question":"おくの委員のほうからもお話があったのですが、全体のバランスという部分ももちろんあって、品川区の方針というものももちろんあると思うのですけれども、本当にこれを機に、やはり八潮地区の特殊性ということもあるのですが、どうしても必要であろうかなという地域に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-032"}]},{"id":"topic-03","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"先ほどのところで質問すればよかったのですけれども、例えば報告第１号のほうは、運転者の住所も名前も出ているではないですか。これどうしてかということを教えていただきたいのと、今の報告第２号なのですけれども、和解したということですが、この方と品川区のということになると思うのですけれども、逆にお名前しか出ていないというのは、どうしてなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"ということはわかったのですけれども、当たり前のことですが、私たちもこのいただいたプリントというか、紙を個人情報として厳格に取り扱わないといけないわけですよね。当たり前かもしれないけれども、これはシュレッダーにかけるなどして、管理を大切にしなければいけないということですよね。改めてお伺いします。","respondent":"川島地域活動課長","answer":"今、委員おっしゃるとおり、議員の皆様には審議していただくためにこのような形で個人情報も載せたものをお出ししていますが、取り扱いについては厳重にしていただきたいです。","voiceIndex":77,"id":"exchange-034"},{"speaker":"湯澤委員","kind":"質問","question":"かもめ橋公衆便所のほうの和解の件なのですけれども、こちらのほうは今、また同じようなことが起きないようにということで、どのような対策をされたかということを教えていただけますか。","respondent":"川島地域活動課長","answer":"こちらのほう、手すりの設置、それからスロープの交換工事等も終わっておりまして、現在ちょうど、今日、明日ぐらいで便器の洋式化工事もされているところというふうに聞いてあります。","voiceIndex":79,"id":"exchange-035"}]},{"id":"topic-04","title":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"今回の議題になかったのですが、新型コロナウイルスの感染拡大に伴って、こちらの所管でさまざまなイベントが行われていると思うのですけれども、そちらのイベントの各所管のこれから行われるイベントの中で、中止にするかどうかを検討しているイベント、もちろん明日の厚生委員会と総務委員会のほうでこちらの対応については話し合いが行われて、最終的に区としての方針が決まると思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"委員長もおっしゃっていたとおり、イベントが中止かどうかということは、もちろん区の情報公開のタイミングを待たなければ、中止するかどうか言えないと思うので、区としての対応を聞いてから、また質問等あれば、そのタイミングでの委員会でまた伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33018,"voices":89}}]);
